// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":108,"question":"يقول هذا السَّائل: رجل تُوفي وترك أربع بناتٍ فقط، وأوصى بثلث ماله في سبيل الله، وبعد خمسة عشر سنة باعوا إحدى العمارات التي ورثت من أبيهم بمليون ريـال، واستثمروا هذا المبلغ في أرضٍ لهم أيضًا ليبنوا عليها شققًا، والآن هم بصدد بيع تلك العمارة التي تُساوي قيمتها الآن أقل من مليون ريـال بكثير، و هل عليهم أن يُخرجوا ثلث مال أبيهم من المليون الأولى، أم يُخرجوا ثلث مال أبيهم مما يستحقّ إذا باعوا هذه العمارة، أم عليهم أن يدفعوا ما عليهم من المليون الأول وقيمة العمارة الثانية؟ أفيدوني جزاكم الله خيرًا","title":"حكم الوصية إذا تَصَرُّف الورثة ببعض التركة","answer":"الجواب: عليهم أن يُخرجوا الثلث من كلِّ شيءٍ، من كلِّ ما خلَّف والدهم، وإذا تسبَّبوا في شيءٍ وباعوا وتسببوا فيه فهو شريكهم فيما يتصرَّفون فيه، ويضمنون ما حصل من النقص إذا فرطوا، ولا بدّ من مشاورة الحاكم في هذه المسائل: المحكمة، الوكيل، فيستشيروا المحكمة في التَّصرفات التي يُريدوها، وإلا فليفصلوا المال الذي يخصّ والدهم وهو الثلث، ويقوم الوكيل فيه بالتَّصرف حسبما أوصى به المُوصي بجعله في عمارةٍ أو غيره بحسب ما أوصى به المُوصي، ويُراجع المحكمة في كل شيءٍ حتى تبرأ ذمتُه، وهو شريكهم في كلِّ شيءٍ، في الدقيق والجليل؛ لأنه موصٍ بالثلث، فهو شريكهم في كل شيءٍ، وليس لهم أن يتصرفوا تصرُّفًا فيه خطر، فإن تصرَّفوا ضمنوا، وإذا أشكل عليهم يُراجعوا المحكمة، والمحكمة تنظر فيما قد يُشكل عليهم، أو يكونوا فرَّطوا فيه، أو نحو ذلك.","link":"https://binbaz.org.sa/fatwas/3544/حكم-الوصية-اذا-تصرف-الورثة-ببعض-التركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0091.mp3","categories":["الوصايا"]},{"id":857,"question":"هل يجوز لأب أن يكتب جزءًا من تركته لأحد أبنائه دون الآخر؟","title":"حكم كتابة الأب جزءًا من تَرِكَته لأحد أبنائه","answer":"الجواب: ليس للأب ولا للأم أن يخصَّ أحدًا من أولاده بشيءٍ، يقول النبي ﷺ: اتَّقوا الله واعدلوا بين أولادكم، فليس للوالد ولا للوالدة تخصيص بعض الأولاد بشيءٍ، لا في الحياة، ولا في الوصية، بل يجب التَّعديل: اتَّقوا الله واعدلوا بين أولادكم.","link":"https://binbaz.org.sa/fatwas/20891/حكم-كتابة-الاب-جزءا-من-تركته-لاحد-ابناىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0686هل يجوز لأب أن يكتب جزءً من تركته لأحد أبناءه دون الأخر؟ ابن باز فتاوى المحاضرات.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":1001,"question":"إذا كنتُ مُسافرًا وحضرت صلاةُ العصر في جماعةٍ، ولم أُصلِّ الظهرَ، فهل أُصلي العصر ثم أُصلي الظهر بعدها، أم أُصلي العصر بنية الظهر؟ أم ماذا أفعل؟","title":"حكم من لم يُصَلِّ الظهر وحضرته العصر","answer":"الجواب: إذا حضر الإنسانُ جماعةً سيُصلون العصرَ في الحضر أو في السفر وهو ما صلَّى الظهر، فإنه يُصلي معهم بنية الظهر؛ من أجل الترتيب، ثم يُصلي العصر بعد ذلك، ولا حرج في ذلك؛ لأنَّ النية لا تُؤثر في هذا، فيُصلي معهم الظهر، ثم إذا سلَّموا صلَّى العصر بعد ذلك في المسجد، أو في بيته، وإن تيسرت جماعةٌ يُصلي معهم العصر صلَّى معهم العصر.\nوهكذا لو جاء وهم يُصلون العشاء، وهو ما صلَّى المغرب، يدخل معهم فيُصلي معهم المغرب بنية المغرب، ويجلس في الثالثة ينتظر، فإذا سلَّم الإمامُ سلَّم معهم، ثم بعد ذلك يُصلي العشاء في المسجد إن تيسر، أو في بيته، فيحصل الترتيبُ وفعل الجماعة، ويُصلي بعد ذلك الصلاة الحاضرة.","link":"https://binbaz.org.sa/fatwas/21054/حكم-من-لم-يصل-الظهر-وحضرته-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0850إذا كنت مسافراً وحضرت صلاة العصر في جماعة ولم أصلي الظهر فهل أصلي معهم العصر بية الظهر.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1232,"question":"إذا كان الإنسانُ نائمًا في الظهر ولم يستيقظ إلا بعد أذان المغرب، فصلَّى المغرب، فتذكَّر أنه لم يُصلِّ العصر: هل يُصليها أم لا؟","title":"حكم مَن صلى بعد نوم ثم تذكر فائتة قبلها","answer":"الجواب:\nنعم، إذا صلَّى المغرب ناسيًا للعصر، ثم ذكرها، يُصلي العصر، وصلاة المغرب مُجزئة، أما التَّعمد لا، لا يتعمَّد، يجب أن يبدأ بالعصر ثم بالمغرب، مثلما فعل النبيُّ ﷺ لما شُغل يوم الأحزاب في قتال الكفرة، شغلوه عن العصر، فصلَّاها بعد الغروب، ثم صلَّى المغرب بعدها، لكن لو نسي وصلَّى المغرب، ثم ذكر أنَّ عليه العصر أو غيرها، صلَّى الفائتة، وأجزأته التي صلَّاها لأجل النسيان: رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، قال الله: قد فعلت.","link":"https://binbaz.org.sa/fatwas/21280/حكم-من-صلى-بعد-نوم-ثم-تذكر-فاىتة-قبلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1023إذا كان الإنسان نائماً في الظهر ولم يستقظ إلا بعد أذان المغرب وتذكر أنه لم يصلي العصر هل يصليها؟.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1288,"question":"هل يجوز إهداء القرآن أو المصحف المُترجم باللغة الإنجليزية لبعض الأطباء غير المسلمين بقصد الدَّعوة؟","title":"ما حكم إهداء ترجمة للقرآن لغير المسلم؟","answer":"الجواب:\nأولًا: أحبك الله الذي أحببتنا له، ونسأل الله أن يجعلنا وإياكم من المتحابين بجلاله، يقول النبيُّ ﷺ: سبعةٌ يُظلهم الله في ظلِّه يوم لا ظلَّ إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلَّقٌ بالمساجد، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، ورجل دعته امرأةٌ ذات منصبٍ وجمالٍ –يعني: إلى الزنا- فقال: إني أخاف الله، ورجل تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شماله ما تُنفق يمينه، ورجل ذكر الله خاليًا –يعني: ما عنده أحد- ففاضت عيناه يعني: بكاء من خشية الله جلَّ وعلا، ويقول النبيُّ ﷺ: يقول الله يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أُظلهم في ظلِّي يوم لا ظلَّ إلا ظلي، نسأل الله أن يجعلنا وإيَّاكم منهم.\nأما نفس المصحف غير المترجم فلا، النبي نهى عن السفر بالقرآن إلى أرض العدو، قال: لئلا تناله أيديهم، لكن إذا أُعطي تفسيرًا أو مترجمًا فلا بأس بالترجمة والتفسير، فإذا أُعطي القرآن المترجم أو تفسير القرآن الذي في ضمنه القرآن فلا بأس، لكن لا يُعطى القرآن المجرد.","link":"https://binbaz.org.sa/fatwas/21347/ما-حكم-اهداء-ترجمة-للقران-لغير-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1090هل يجوز أهداء ترجمة للقرآن لغير المسلم؟ ابن باز فتاوى.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":1320,"question":"بالنسبة للوالد هل له أن يرجع في صدقته على ولده؟","title":"هل للوالد الرجوع في صدقته على ولده؟","answer":"الجواب:\nله الرجوع بنص النبي عليه الصلاة والسلام، إلا الوالد يعطي ولده له الرجوع.","link":"https://binbaz.org.sa/fatwas/21411/هل-للوالد-الرجوع-في-صدقته-على-ولده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للوالد الرجوع في صدقته على ولده.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":1468,"question":"يقول السائل: ما حكم الوصية للأقارب غير الوارثين؟ هل هو واجب أم سُنة؟","title":"حكم الوصية للأقارب غير الوارثين","answer":"الجواب:\nمستحبة، مساعدة الأقارب غير الورثة مستحبة، يعني الوصية لهم. أما الورثة فلا؛ يقول النبي ﷺ: لا وصية لوارث.\nس: يكون من الثُّلُث؟\nج: من الثلث فما دونه.","link":"https://binbaz.org.sa/fatwas/21565/حكم-الوصية-للاقارب-غير-الوارثين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الوصية للأقارب غير الوارثين.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1490,"question":"سائلة تقول: فتحتُ حسابًا في بنك الراجحي، فاتصل عليَّ قسم النساء وأعطوني هديةً ساعة مقابل هذا الرصيد، فماذا أفعل بها؟","title":"حكم هدايا البنوك للعملاء مقابل الرصيد","answer":"الجواب:\nرصيد أيش؟\nس: رصيد في البنك، فقد وجدوا أنَّ أموالها كثيرة فقالوا: أنت تستحقين هذه الهدية: ساعة قيمة، تقول السائلة: أنا استلمتها فماذا أفعل بها؟\nج: الأحوْط لها والذي يظهر أنها تبيعها وتتصدق بها، وإلا تردها عليهم حتى يفهموا أنَّ هذا ما هو طيب.","link":"https://binbaz.org.sa/fatwas/21588/حكم-هدايا-البنوك-للعملاء-مقابل-الرصيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في هدايا البنوك.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":1605,"question":"والد أوصى في وصيته لأبنائه بأن يُضحُّوا له كل سنةٍ، فمضت أيام التَّشريق في إحدى السنوات ولم يُضحّوا، فما الواجب عليهم؟","title":"حكم من أخلّ بوصية والده أن يُضَحَّى عنه","answer":"الجواب:\nيعني: هو الذي أوصى به؟\nس: نعم.\nج: يذبحونها ولو بعد العيد.\nس: هل عليهم التوبة؟\nج: نعم، عليهم التوبة إذا كانوا تعمَّدوا، حتى ولو من مالهم..... لو تصدَّق عنه بذبيحةٍ في أي وقتٍ، تصدَّق بها على الفقراء فله أجر.\nس: إذا لم يكن له مالٌ وإنما أوصى الأولاد أن يذبحوا؟\nج: إذا تيسر لهم.\nس: يعني ما هو واجب؟\nج: لا، ما هو واجب: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ ۝ وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:14- 15]، فمع كونهما جاهداه في الشرك قال الله له: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا بالإحسان إليهما وبرّهما، وإن كانا مشركين، فلعل الله يهديهما بسبب برّه لهما، والإحسان إليهما، والرفق بهما، لعلهما ولعلهما.","link":"https://binbaz.org.sa/fatwas/21709/حكم-من-اخل-بوصية-والده-ان-يضحى-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أوصى أولاده بأن يضحوا له كل عام ولم يستطيعوا.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1996,"question":"الإشهاد في الهبة مستحب وإلا واجب؟","title":"حكم الإشهاد في الهبة","answer":"الجواب:\nنعم، أشهد على هذا غيري لأجل قد يرجع الواهب، وقد تتغير الأمور، فالإشهاد أقل أحواله الاستحباب، مثل الإشهاد في البيع وَأَشْهِدُوا إِذَا تَبَايَعْتُمْ [البقرة:282] أقل أحواله الاستحباب.\nس: سماها صدقة (ورجع أبي في تلك الصدقة)؟\nالشيخ: على ولده...\nس: تسمى الهبة والعطية \"صدقة\"؟\nالشيخ: إذا أراد الأجر صارت صدقة.\nس: الإمام أو القاضي أو الوالي لا يَشْهد؟\nالشيخ: إذا أشهدهم أشهدهم على عطية أو على بيع، ما في حكمها، هذه شهادة.\nس: بالنسبة لإعطائه المكافأة تشجيعًا له؟\nالشيخ: لا يخصه بشيء إلا النفقة الواجبة، النفقة الواجبة لا بأس، كُلٌّ يُعطى على قدره، أما إذا كان مجرد تشجيع هذا على حفظ وإلا كذا، لا، لا يعطيهم، يشجّعهم بالكلام، وإلا إذا أعطاه تشجيعًا يُعْطِي الآخرين مثله.","link":"https://binbaz.org.sa/fatwas/22112/حكم-الاشهاد-في-الهبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الإشهاد في الهبة.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":1998,"question":"التسوية بين الأولاد حتى لو كان بعضهم يصلي وبعضهم لا يصلي؟","title":"حكم التسوية في الأعطية للولد الذي لا يصلي","answer":"الجواب:\nلا، الكافر ما له حق، إذا كان كافرًا ما له حق. الكلام في أولاده المسلمين، الكافر الذي يترك الصلاة كافر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22114/حكم-التسوية-في-الاعطية-للولد-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يتساوى الأولاد في الأعطية إذا كان أحدهم يصلي والآخر لا يصلي.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":2095,"question":"أوصى المُوصِي بوصيَّةٍ ولم يقبلها المُوصَى له؟","title":"حكم الوصية إذا لم يقبلها المُوصَى له","answer":"الجواب:\nإذا ما قبلها تصير للورثة.\nس: للورثة أم لبيت المال؟\nج: لا، للورثة، ورثة الموصِي.","link":"https://binbaz.org.sa/fatwas/22213/حكم-الوصية-اذا-لم-يقبلها-الموصى-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أوصى المُوصِي ولم يقبلها المُوصَى له.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":2150,"question":"هل الشَّرْهات والمَنَاخ تُعتبر من بيت المال؟","title":"هل \"الشّرْهة\" و\"المَنَاخ\" تُعتبر من بيت المال؟","answer":"الجواب:\nهذا من سؤال السلطان من بيت المال، فالشيء المعتاد لا بأس به، إلا أن يسأل سلطانًا أو في أمرٍ لا بد منه، كما تقدم.","link":"https://binbaz.org.sa/fatwas/22269/هل-الشرهة-والمناخ-تعتبر-من-بيت-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سؤال السلطان من بيت المال والمسألة في الكتب الخاصَّة بالتَّوزيع.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":2176,"question":"مدير إدارة يأتي إليه الموظفون بالحلا والبسكوت وبعض المأكولات وبعض المشروبات كالشاي والقهوة؟","title":"حكم إهداء الهدايا لمدير الإدارة","answer":"الجواب:\nيهدون إليه من أموالهم أم من الإدارة؟\nس: يهدون له من أموالهم.\nج: لا، لا يأخذ منهم شيئًا، يُشبه الأمير، ولا يأخذ شيئًا؛ لأنه قد يُسبب له مشاكل.","link":"https://binbaz.org.sa/fatwas/22297/حكم-اهداء-الهدايا-لمدير-الادارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إهداء الهدايا لمدير الإدارة.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":2184,"question":"كتابة الوصية هل هي واجبة؟","title":"ما حكم كتابة الوصية؟","answer":"الجواب:\nلا، مستحبة، لكن إذا كان له شيء يخشى عليه، مثل: ديون ما عليها وثائق، فعليه أن يُثبتها للناس حتى لا تضيع حقوقهم، أمَّا إذا لم يكن عليه شيء وإنما هي مجرد صدقة فمستحبٌّ له إذا كان عنده شيء يُوصي فيه، إذا كانت عنده سعة.","link":"https://binbaz.org.sa/fatwas/22306/ما-حكم-كتابة-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كتابة الوصية.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":2206,"question":"بالنسبة لهذا المَنَاخ: هناك بعض الشّرهات التي تُسمَّى هذه الأيام، فإذا أردتُ شرهةً مثلًا أجعل للموظف خمسة آلاف ريـال حتى يتوسَّط لي عند الدولة، فهل هذا جائز؟","title":"حكم مَن يدفع لموظف ليتوسَّط في مال الدولة","answer":"الجواب:\nلا، الشفاعة ما يُؤخذ عليها شيء، أما إذا كانت لك معاملة وتطلب أن يكون لك مناخ، ووكلتَ إنسانًا بمتابعة المعاملة، فهو مثل الدّلال، يُعطى أجره عن متابعته، أما الشفاعة فلا، الشفاعة ما يصلح، ما يُعطى شيئًا.","link":"https://binbaz.org.sa/fatwas/22329/حكم-من-يدفع-لموظف-ليتوسط-في-مال-الدولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ما يأتي للإنسان من الأموال التي تقرها الدولة.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":2241,"question":"أحد الإخوان يُهدَى إليه كثيرًا ويردّ الهدايا، لا هو في مركزٍ وليس له سبب حتى يرد الهدية؟","title":"حكم مَن يَرُدُّ الهدايا مِن غير سبب ظاهر","answer":"الجواب:\nالسُّنة قبول الهدية، والإثابة عليها، فالنبي عليه الصلاة والسلام يقول: تهادوا تحابّوا، وكان يقبل الهديةَ، ويُثِيب عليها، ولا يردّها إلا لعِلَّةٍ.\nس: وقوله: لا تُهدي لي فتُكلّفني فوق طاقتي؟\nج: إذا كان يُهدي له أموالًا يردّها عليه، لا بأس، إذا كان يريد العِوض من هديته.\nس: لا، ما يُريد العِوض، لكنه يردّها كثيرًا، هكذا حتى ضاق صدرُ أخيه؟\nج: يمكن أنه يتَّهمه بأنه يُريد العِوض.\nس: ما يتّهمه أبدًا.\nج: السُّنة قبول الهدية إلا إذا كان من علَّةٍ.\nس: مَن أخذ الهديةَ وبعد ذلك أهداها، هل هناك شيء في هذا؟\nج: لا بأس، فهذا ملكه يتصرّف فيه كيف يشاء.","link":"https://binbaz.org.sa/fatwas/22364/حكم-من-يرد-الهدايا-من-غير-سبب-ظاهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أهدي له هدايا ويردها.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":2276,"question":"امرأة لها ابنان، ولها مِلكٌ عبارة عن منزلٍ، واشترطت أنه إذا تُوفي الابنُ الصَّغير أن يحلّ محله ابنه كالسّبالة؟","title":"ما حكم الوصية لابن الابن والأجنبي؟","answer":"الجواب:\nإذا أوصت لهم؛ لا بأس، بقدر الثلث، ما لهم إلا قدر الثلث، إلا أن يرضى بقيةُ الورثة.\nس: الابنان شريكان في المنزل بعد ورثهما أمّهما؟\nج: المقصود أنها إذا أوصت لأولاد ولدها تكون الوصيةُ ناجزةً لا بأس بها، لكن بالثلث فأقل.\nس: هي أوصت لأحد ..؟\nج: أو لأجنبي لا بد أن يكون بالثلث فأقل.\nس: أوصت لأبناء أحد الابنين، هل يجوز ذلك؟\nج: بالثلث فأقل؛ لأنَّه ما يرث، فالابن مع الابن عمُّهم يمنعهم، ما هم بورثةٍ، فإذا أوصت لهم بالثلث أو بأقل كالربع والخمس لا بأس.\nس: الموصي ولو كان ماله قليلًا؟\nج: ولو كان ماله قليلًا إذا أوصى.","link":"https://binbaz.org.sa/fatwas/22399/ما-حكم-الوصية-لابن-الابن-والاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اشتراك الأبناء في الميراث.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":2940,"question":"في الحديث أن النبي ﷺ وَجَد على صفية في نفسه شيئًا فقالت صفية رضي الله عنها لعائشة رضي الله عنها: هل لك أن تُرضي النبي ﷺ عني وأهَبُ لك يومي، والحديث طويل، فالحديث يرد عليه إشكال: أنه هل تُقبل الهدية في الشفاعة؟","title":"ما حكم الهدية التي تُعطى في الشفاعة؟","answer":"الجواب: لا، إلا إذا سمح بها الزوج، إذا سمح بها الزوج؛ فلا بأس.\nس: عائشة رضي الله عنه قبلت يوم صفية رضي الله عنها؟\nالشيخ: يوم سَوْدة، سودة لما أراد طلاقها، قالت: يا رسول الله أمسكني في حبالك ويومي لعائشة، فقبل النبي ﷺ. فإذا قبل النبي من الزوجة لا بأس.\nس: ما يعتبر من قبول الهدية في الشفاعة؟\nالشيخ: لا ما في شيء؛ لأن هذا إسقاط حق.","link":"https://binbaz.org.sa/fatwas/23096/ما-حكم-الهدية-التي-تعطى-في-الشفاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقبل الهدية في الشفاعة.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":3143,"question":"هناك بعض محطات البنزين يضعون لمن يشتري منهم بمائة وعشرين ريالًا بنزين غسيل سيارة مجانًا، فما حكم هذا الغسيل؟","title":"حكم عرض المحطات غسيل السيارة مجانًا","answer":"الجواب: تَرْكُه أحسن؛ لأن هذا يرغبون في السَّوْم حتى يتعطل الآخرون، تَرْك هذا أحسن وأوْلى.\nس: وإن فعل ما يُنْكر عليه؟\nالشيخ: والله تَرْكُه أوْلى، الأحوط عندي؛ لأنه قد يَبْذِل أموالًا لعله يُحَصّل هذا، نعم.","link":"https://binbaz.org.sa/fatwas/23305/حكم-عرض-المحطات-غسيل-السيارة-مجانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ما يفعله بعض المحطات لمن يشتري منهم بمبلغ معين غسيل سيارة مجانا.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":3540,"question":"أعطى فلانًا عطية، وهو أراد أن يُعطي غيره؟","title":"هل يجوز الرجوع في الأعطية؟","answer":"الجواب: ليس له الرجوع في العطية، إلا الوالد فيما يعطي ولده.\nس: يعطي غيره؟\nالشيخ: لا، ليس له الرجوع، الرسول ﷺ نهى عن الرجوع في الهدية.","link":"https://binbaz.org.sa/fatwas/23722/هل-يجوز-الرجوع-في-الاعطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز الرجوع في الأعطية.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":3674,"question":"بالنسبة لقبول الهدية..؟","title":"هل قبول الهدية واجب أم مستحب؟","answer":"الجواب: محل نظر، والمشهور عند العلماء الاستحباب، وعلى المُهدَى له أن يقابل الهدية، كان النبي ﷺ يقبل الهدية ويثيب عليها، يعني يعطيهم مقابلًا؛ لأن بعض الناس قد يهدي للمقابل، فإذا قبلها أعطاه مقابل ذلك، يعني أثابهم عليها، وفي الحديث الآخر: تهادوا تحابوا.","link":"https://binbaz.org.sa/fatwas/23863/هل-قبول-الهدية-واجب-ام-مستحب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الهدية وقبولها.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":4196,"question":"لو كانت العطية لا تصلح إلا له، ولا تصلح لغيره؟","title":"حكم العطية التي لا تصلح إلا لواحد من الأولاد","answer":"الجواب: المقصود مثل ما قال ﷺ: اتقوا الله واعدلوا بين أولادكم فإذا سمحوا وهم مرشدين، إذا شاورهم وسمحوا فلا بأس،...... إذا سمحوا لأخيهم لحاجة وهم مرشدون؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/24454/حكم-العطية-التي-لا-تصلح-الا-لواحد-من-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم العطية إذا كانت لا تصلح إلا لواحد فقط من الأولاد.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":4878,"question":"رجوع المرأة في هبتها لزوجها؟","title":"هل للمرأة الرجوع في هبتها لزوجها؟","answer":"إذا كانت لها أسباب كأن تعطيه تخاف أن يطلق وطلق؛ ترجع، أما إذا كانت أعطته لفقره وحاجته، ما هو خوف من طلاق؛ ليس لها الرجوع، تعمها الأحاديث. المقصود أن ينظر في القرائن وأن يتقي الله؛ فإذا كانت القرائن أنها أعطته خوفًا من شره أو خوفًا من طلاقه أو خوفًا أن يتزوج، فإذا خالف ما رأت يرد عليها الهدية.","link":"https://binbaz.org.sa/fatwas/25382/هل-للمراة-الرجوع-في-هبتها-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للمرأة الرجوع في هبتها لزوجها.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":4879,"question":"هل الهدية تُهدى وتُباع؟","title":"هل الهدية تُهدى وتُباع؟","answer":"نعم.\nس: بعضهم يقول: لا تهدى ولا تباع؟\nج: لا، هذا كلام جاهل.","link":"https://binbaz.org.sa/fatwas/25383/هل-الهدية-تهدى-وتباع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الهدية تهدى وتباع.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":4880,"question":"من كان يتعامل بالربا هل تُقبل هديته؟","title":"هل تُقبل هدية من يتعامل بالربا؟","answer":"ولو، إذا كان ما هو كل ماله ربا. الله أباح لنا طعام اليهود وهم يتعاملون بالربا، والنبي ﷺ اشترى منهم طعامًا ورهنهم درعه.\nأما إذا كنت تعلم أنها من مال الربا أو كل ماله ربا لا تأخذها.\nس: هو يعمل في بنك وليس له مورد إلا من هذا البنك؟\nج: لا تقبلها.","link":"https://binbaz.org.sa/fatwas/25384/هل-تقبل-هدية-من-يتعامل-بالربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقبل هدية من يتعامل بالربا.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":4882,"question":"هل تقدم الوصية على الدين؟","title":"هل يجوز تقديم الوصية على الدين؟","answer":"لا، الدين مقدَّم على كل شيء مِنْ بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ [النساء:11] قضى النبي ﷺ بالدين قبل الوصية.","link":"https://binbaz.org.sa/fatwas/25387/هل-يجوز-تقديم-الوصية-على-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما يقدم الوصية أم الدين.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":5006,"question":"المَنَاخ إذا كان يأتي لرجلٍ وهو في غنًى عنه؟","title":"حكم مَن يأتيه مال من الدولة وهو غني عنه","answer":"الجواب: ولو، فالمَنَاخ هذا من بيت المال، والمهاجرون والأنصار فيهم الأغنياء، وعمر فرض لهم عادةً سنويةً، فهو على حسب ما تُقرّه الدولة: إن رأت قطعه تقطعه، وإن رأت أن تُعطيه مَن خلفه، إن كان خلفه أيتام أو فقراء، أو تقطعه؛ فهذا يرجع إلى الدولة.","link":"https://binbaz.org.sa/fatwas/28808/حكم-من-ياتيه-مال-من-الدولة-وهو-غني-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يأتيه مال من الدولة وهو غني عنه.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":5184,"question":"ما حكم الهدية في الإسلام؟ هل تُقبل أو تُرد؟","title":"ما حكم الهدية في الإسلام؟","answer":"الجواب: الأصل في الهدايا أنها تُقبل، كان النبيُّ ﷺ يقبل الهدية ويُثِيب عليها. رواه البخاريُّ من حديث عائشة. إلا إذا كانت ثمنًا لدِينه: كالذي يُدفع للقاضي ليجور وليخون وليحيف، أو لموظفٍ ليخون، فلا يأخذ. ما يُهدى للعمَّال ليحيفوا ولا يؤدُّوا الحقَّ؛ تكون رشوةً. أما الهدايا في أصلها فهي قربة، ومن أسباب التَّحاب، ولكن ينبغي لمَن أُهدي إليه شيءٌ أن يُثيب المُهدي، وأن يُقابله مقابل هديته، إذا كانت من باب الهدايا، أما إذا كانت من باب الصَّدقات فلها شأنٌ آخر.","link":"https://binbaz.org.sa/fatwas/30121/ما-حكم-الهدية-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 146.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":5322,"question":"ما هو القول الصحيح في الوصية الواجبة، ومن قال بالوصية الواجبة من العلماء؟","title":"ما حكم الوصية؟ ومتى تكون واجبة؟","answer":"الجواب: الوصية الواجبة من الحقوق التي عليه، يجب عليه أن يوصي بالديون التي ما عليها بيّنات؛ كفارات، حقوق عليه للناس، يلزمه أن يُوصِي بها. الحق الذي عليه لله أو لعباده يوصي به، وأما الوصية بالثلث، بطاعة الله، أو بالربع، أو بالخمس، هذه مستحبة.[1]","link":"https://binbaz.org.sa/fatwas/30985/ما-حكم-الوصية-ومتى-تكون-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 042.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":5473,"question":"مَن يتعامل بالربا هل تُقبل هديته أو عطيته؟","title":"هل تُقبل هدية مَن يتعامل بالربا؟","answer":"الجواب: إذا كانت أمواله كلها ربا لا، أما إذا كانت له أعمال ربوية وأعمال أخرى فلا بأس؛ مثلما اشترى النبي من اليهود وهم يتعاطون الربا، اشترى منهم طعامًا؛ لأنهم يأكلون الربا، وعندهم أعمال أخرى، أما إذا كان لا، إنسان ما عنده دخل إلا الربا فلا، لا تُقبل معاملته. س: من كان عنده مال مختلط بين الحلال والحرام هل يخشى عليه من عدم؟ ج: المختلط لا بأس أن يُعامل، وهو عليه أن يتَّقي الله ويحذر. س: هل يخشى عليه من عدم قبول الدعاء؟ ج: وهو من أسباب عدم قبول الدعاء، أكل الربا وأكل الحرام من أسباب عدم قبول الدعاء.[1]","link":"https://binbaz.org.sa/fatwas/31351/هل-تقبل-هدية-من-يتعامل-بالربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/reyath_alsalhin 008.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":5670,"question":"ما الواجب على الوالد في عطيته وهبته لأولاده إذا كان فيهم ذكور وإناث؟ هل يجب أن يُعطي البنت نصف ما يُعطي الولد؟","title":"هل يلزم في أعطية الوالد أن تكون وفق الميراث؟","answer":"الجواب: الواجب العدل؛ لأنَّ الرسول يقول: اتَّقوا الله واعدلوا بين أولادكم، فلا بدَّ أن يُسوي بينهم: لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ [النساء:11] مثل الإرث، فإذا أعطى الرجلَ ألفًا يُعطي المرأة خمسمئة، لا بدَّ من التعديل بينهم، إلا إذا كانوا مُرشدين وسمحوا لواحدٍ يُعطى زيادةً، وهم مُرشدون وسمحوا عن طيب نفسٍ فلا بأس. أما إذا كانوا غير مُرشدين لا، لا بدَّ من التعديل، يُسوي بينهم، ولا يُعطي هذا ويدع هذا، الرجل والمرأة، المرأة لها نصف الرجل، وإن كانت مُتزوجة، لا بدَّ أن يُسوي بينها وبين إخوتها، ولا يظلم، يعدل بين الجميع، الرسول يقول: اتَّقوا الله واعدلوا بين أولادكم. س: وهل إذا اشترى سيارةً أو أرضًا أن يفعل مثله مع بقية إخوانه؟ ج: سيارة أو غيرها، إلا إذا كانت باسمه عارية، يذهب بها للمدرسة، وهي باسم الوالد، ما هي بعطيَّة، لكن يذهب بها للمدرسة ويرجع، وهي باسم الوالد؛ لا بأس. أما عطية لا، لا يُعطيه عطية دون إخوته.[1]","link":"https://binbaz.org.sa/fatwas/31707/هل-يلزم-في-اعطية-الوالد-ان-تكون-وفق-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 016.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":5802,"question":"وجدنا حديثًا عن أبي هريرة قال: قال رسول الله ﷺ: \"إن الرجل ليعمل بعمل أهل الخير سبعين سنة، فإذا أوصى، وحاف في وصيته؛ فيختم له بشر عمله، فيدخل النار\" ما معنى حاف، وأفيدونا عن ذلك، جزاكم الله؟","title":"المراد بالحيف في الوصية","answer":"الجواب: جاء في هذا المعنى عدة أحاديث عن النبي ﷺ، عن ابن مسعود في الصحيحين، وأحاديث أخرى: أن العبد يعمل بعمل أهل الجنة حتى ما يكون بينه وبينها إلا ذراع، فيسبق عليه الكتاب فيعمل بعمل أهل النار، فيدخل النار، يعني يختم له بخاتمة سوء، نعوذ بالله. وفي بعض الروايات: إن العبد ليعمل بعمل أهل الجنة فيما يبدو للناس، يعني: في ظاهر حاله، وفي آخر حاله، يعمل بعمل أهل النار، فيدخل النار، نعوذ بالله، وإن العبد ليعمل بعمل أهل النار فيما يبدو للناس، ثم في آخر حاله يعمل بعمل أهل الجنة، فيتوب الله عليه؛ فيدخل الجنة، فالأعمال بالخواتيم. والحيف في الوصية: كونه يوصي بما لا يجوز له، يوصي لوارث، فالوارث ليس له وصية، بل يكفيهم ما قسم الله لهم إن الله قد أعطى كل ذي حق حقه فلا وصية لوارث والحيف في الوصية كونه يزيد على الثلث بغير إذن الورثة، أو يوصي لبعض الورثة، فهذا لا يجوز، بل الواجب عليه أن يقتصر على الثلث فأقل، وألا يوصي للورثة. أما هذا الحديث؛ فلا أعلم حال سنده، يحتاج إلى نظر في سنده، ولكن معناه أنه إذا عمل سيئة في آخر حياته، ومعصية، ومات عليها؛ يخشى عليه من النار بسبب سوء الخاتمة، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1131/المراد-بالحيف-في-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_137.mp3","categories":["الوصايا","الحكم على الأحاديث"]},{"id":5809,"question":"بالنسبة لمن يبني مسجدًا، ويأمر بدفنه فيه؛ قياسًا على فعل الرسول؟","title":"بنى مسجدًا وأوصى أن يدفن فيه","answer":"الجواب: لا، لا يدفن؛ لأن الرسول ما دفن في المسجد، الرسول دفن في الحجرة في بيته، لكن لما وسع الوليد أدخل الحجرة، وضمها إلى المسجد. فالنبي ما دفن في المسجد ﷺ دفن في بيته، بيت عائشة، ولكن بعض أمراء القرن الأول أدخله في المسجد للتوسعة، أدخل الحجرة برمتها، وقد غلط في ذلك، ولكن وقع ما وقع.","link":"https://binbaz.org.sa/fatwas/1133/بنى-مسجدا-واوصى-ان-يدفن-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_139.mp3","categories":["الوصايا","حمل الميت ودفنه"]},{"id":5832,"question":"ما حكم من يوصي بدفنه في محل قد دفن فيه أهله، وأولاده، هل ننفذ وصيته، أم لا؟","title":"حكم من أوصى بأن يدفن في مقبرة دفن فيها أقاربه","answer":"الجواب: إذا أوصى بأن يدفن في المقبرة التي دفن فيها أقاربه؛ فلا بأس، إذا كان ما في كلفة، أما إذا كان فيه كلفة مثل نقله من بلاد إلى بلاد، ما في حاجة، يدفن مع المسلمين في أي مكان، لكن إذا كان في البلاد، ولا فيه كلفة؛ فهذا حسن، حتى تسهل زيارتهم، حتى الذي يزورهم يزورهم جميعً في مقبرة واحدة فيه مصلحة. لكن إذا كان فيه كلفة، وخسائر، ونفقة فلا حاجة إلى هذا الشيء، ولا تنفذ هذه الوصية، فالذي ينقل من بلاد إلى بلاد، وفيه موجب، وفيه كلفة على أهل الميت، وقد يكون ثقيل، وقد يكون أهله فقراء. فالحاصل: أنه لا أصل للنقل، ولم يكن الصحابة ينقلون من بلد إلى بلد، رضي الله عنهم وأرضاهم. فالأفضل عدم النقل إلا من حاجة إلا من مصلحة، كالذي يموت بين الكفار، ينقل، يدفن بين المسلمين، لا بأس، وإن نقل ليدفن بين أهله بدون مشقة؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/1165/حكم-من-اوصى-بان-يدفن-في-مقبرة-دفن-فيها-اقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_164.mp3","categories":["حمل الميت ودفنه","الوصايا"]},{"id":5836,"question":"إذا توفى في الرياض، وقال: ادفنوني في المدينة؟","title":"حكم من أوصى أن يدفن في بلد غير بلده","answer":"الجواب: لا، ما هو بمشروع هذا، إذا مات في الرياض لا ينقل إلى المدينة، ولا لغير المدينة، وإذا مات في الخرج ما ينقل للرياض، وإذا مات في الخرج لا ينقل إلى الحوطة، وهكذا ما له حاجة، تكلف بلا حاجة، الأولى عدم تنفيذ هذه الوصية.","link":"https://binbaz.org.sa/fatwas/1166/حكم-من-اوصى-ان-يدفن-في-بلد-غير-بلده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_165.mp3","categories":["حمل الميت ودفنه","الوصايا"]},{"id":6457,"question":"أرجو إيضاح الرد على هذه الشبهة التي يروج لها دعاة تحديد النسل، وهي قولهم أن هناك حديث لرسول الله ﷺ يقول: إياكم وكثرة العيال؛ فلأن تترك ورثتك أغنياء خير لك من أن تتركهم فقراء يسألون الناس فما مدى صحة هذا الحديث، وما الرد على هؤلاء؟","title":"الرد على شبهة إياكم وكثرة العيال","answer":"الجواب:  هذا القائل جمع حقًا، وباطلاً (إياك وكثرة العيال) هذا باطل ما له أصل، ما قال النبي ﷺ: إياكم وكثرة العيال، نسأل الله العافية، هذا باطل منكر، هذا شيء موضوع ما له أصل، إنما قال لسعد لما قال سعد: يا رسول -وهو مريض، سعد بن أبي وقاص الزهري  أحد العشرة المشهود لهم بالجنة- في حجة الوداع قال : أنا ذو مال -وهو مريض  ذاك الوقت- وليس لي إلا ابنة واحدة، أفأتصدق بثلثي مالي؟ قال: لا قال: فالشطر؟ قال: لا قال: فالثلث؟ قال: الثلث، والثلث كثير، إنك أن تذر ورثتك أغنياء خير من أن تذرهم عالة يتكففون الناس. فالنبي ﷺ قال له: لا يتصدق بأكثر من الثلث، يعني يبقي المال للورثة، ولا يوصي بأكثر من الثلث، لا يتصدق، وهو مريض بأكثر من الثلث، وبين له أنه إذا ترك ورثته أغنياء خير من تركهم عالة -يعني فقراء- يتكففون الناس، يسألون الناس.  فهذه وصية بالإحسان إلى الذرية، وأن يبقي لهم مالًا ينفعهم بعد وفاته، وليس فيه توصية بترك كثرة العيال، لا، هذا منكر وليس له أصل عن النبي ﷺ وإنما هذا من كلام النبي ﷺ بالوصية للرجال أن يتركوا لأولادهم وذرياتهم شيئًا ينفعهم من المال، وألا يتصدقوا في أمراضهم، لا يتصدقون في مرضهم، ولا يوصون بمالهم في مرضهم، وليس لهم من ذلك إلا الثلث في حال المرض، وليس لهم بالوصية إلا الثلث حتى يبقى المال للورثة، وللذرية ينتفعون به، ويستفيدون منه، وحتى لا يبقى الذرية عالة فقراء يحتاجون إلى سؤال الناس، هذا كلامه ﷺ.","link":"https://binbaz.org.sa/fatwas/2194/الرد-على-شبهة-اياكم-وكثرة-العيال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_819.mp3","categories":["الوصايا","الحكم على الأحاديث"]},{"id":6681,"question":"توفي جدي وله أربعة من العيال، ولدين وبنتين، فأوصى بقسم من بيته لبنات ولده، علمًا أن له عيال، فهل يجوز لنا تنفيذ ما أوصى به لبنات ولده، وما حكم الإسلام في ذلك؟","title":"حكم الوصية لبنات الولد","answer":"الجواب: الوصية لغير الوارث لا بأس بها، الوصية للوارث ممنوعة، أما الوصية لغير الوارث من أولاد أولاده من غير الوارثين لا بأس بها .. فله أن يوصي لغير الورثة بالثلث، فأقل، أما الورثة فليس يوصي لهم لا بقليل، ولا بكثير، أما غير الورثة كجد أم أبي أمه، وكأولاد بناته، وكأولاد إخوته، وكذا إخوته غير الوارثين؛ لأن له أولادًا، له أن يوصي بما يشاء بالثلث، فأقل، لكن إذا كان له أولاد، فالواجب العدل بينهم، إذا كان له أولاد  فلا يوصي لبعضهم دون بعض اتقوا الله واعدلوا بين أولادكم فيوصي للجميع، أو يدع الجميع. السؤال: ولو أوصى لأحد الورثة بإجازة الباقين؟ الجواب: إذا أجاز الباقون؛ فلا بأس للحديث، إلا أن يشاء الورثة، الحق لهم إذا أجازوه هم، إذا أجازوا وهم مرشدون، لا صغارًا، إذا أجازوه وهم مرشدون فلا بأس.","link":"https://binbaz.org.sa/fatwas/2550/حكم-الوصية-لبنات-الولد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1045.mp3","categories":["الوصايا","حمل الميت ودفنه"]},{"id":7059,"question":"والدي توفي منذ سنتين، وقد أوصاني -رحمه الله- بأن أكون في الوصية على ثلثه، وقد أخذت المال، وكان المبلغ لا بأس به، واشتريت به بضائع، وربح، والحمد لله، وأنا إن بعت، وزاد هذا المبلغ، وبدأت أعطي منه صدقات، وأعطي للمحتاج، وكذلك إذا أراد أحد دينًا؛ فإني أعطيه من ذلك المال، أما بالنسبة لي فإني آخذ منه دينًا إذا احتجت لذلك، وأقوم بإرجاعه، هل في هذا الأخذ شيء؟ أرجو أن تخبرني جزاك الله خيرًا، هل هو حلال أو حرام؟","title":"حكم الاقتراض من الثلث الموصى به في مجالات الخير","answer":"الجواب:\n\nهذا فيه خير كثير، ومصلحة، هذا على كل حال عمل طيب، وسعيها في تنميته، وكل ما ينفع الميت هذا كله طيب، وإن جعل في عقار يكون أثبت، في بيت، أو دكان، أو نخل .. يمكن شراء العقار، يكون أسلم وأثبت، وإلا فهذا عمل طيب، كونها تشتري به سلعًا، وينمو، وتعتني بأسباب الربح، وتتصدق بذلك. \n\nأما كونها تقترض فلا تقترض، وينبغي ألا تقترض من ذلك، بل تحفظه، وتعمل فيه ما ينميه، ويكثر ريعه، وهي لا تقترض.\n\nأما إن أرادت شيئًا من الربح؛ تراجع ولي الأمر، تراجع المحكمة، والمحكمة تفرض لها شيئًا، نصف الربح، أو ثلث الربح، أو ربع الربح، أو ما أشبه ذلك مما تراه المحكمة.","link":"https://binbaz.org.sa/fatwas/3048/حكم-الاقتراض-من-الثلث-الموصى-به-في-مجالات-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1441.mp3","categories":["الوصايا","حمل الميت ودفنه"]},{"id":7082,"question":"أفيد فضيلتكم أن والدي توفي، وقد أوصى بثلث ماله، يجعل في عقار يريع، يخرج من ريعه أضحية، وباقي ريعه يصرف في أعمال البر والخير، أفيد فضيلتكم بأن ثلث ماله لا يكفي في شراء عقار، فأرجو من فضيلتكم أن يبين لنا في أي شيء يوضع هذا المال؟","title":"حكم من أوصى بالاستثمار في شيء ولم يبلغ ثمنه","answer":"الجواب:\n\nإذا تيسر بعقار، ولو مشاعًا مثل سهم في بيت في عمارة، في أرض تغل في نخل اشتروا به، يعني ربع نخل، ثلث نخل، نصف نخل، نخلات معلومة في محل مرغوب حتى تضحوا منها كل سنة، والباقي في أعمال البر، يصرف في الفقراء، والمساكين، وعمارة المساجد، وحاجات المساجد، ونحو ذلك.\n\nأما إذا كان قليلًا، ما في حيلة، هذا يصرفه في جهة نافعة، مثل عمارة المساجد، وأشباهها، وإن ضحيتم منه حتى ينتهي، أو جعلتموه عند إنسان يتجر فيه، ويضحى من غلته، ويتصدق من غلته إذا تيسر من يقوم بذلك من الناس الطيبين الأمناء، يتجرون فيه، ثم يتصدق من غلته، ويضحى من غلته؛ لا بأس، أما إذا ما تيسر أن يقوم بذلك، ولا حصل من يتجر فيه؛ فإنه يجعل في مثل المسجد؛ حتى ينتفع بصلاة المسلمين فيه، وإقامة الحلقات العلمية فيه، ونحو ذلك، إذا كان قليلًا، ما فيه حيلة.","link":"https://binbaz.org.sa/fatwas/3078/حكم-من-اوصى-بالاستثمار-في-شيء-ولم-يبلغ-ثمنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1462.mp3","categories":["الوصايا","حمل الميت ودفنه"]},{"id":7515,"question":"سؤاله الثاني يقول: أنا أسافر إلى الكويت ويأتيني واحد فيقول: اشتر لي ساعة معينة من سوق الكويت، وأتفق معه على أن يعطيني فائدة وأتعاب زائدة عن الفاتورة ثلاثة في المائة، فهل هذا جائز شرعاً؟","title":"حكم أخذ الأجرة على الوكالة في البيع","answer":"الجواب: إذا اتفق معه على أجرة ثلاثة في المائة عن تعبه لشراء الساعة لا بأس، إذا اتفق معه أن يشتري الساعة كوكيل، ولكنه يعطيه في مقابل ذلك ثلاثة في المائة أو خمسة في المائة عن تعبه، لا حرج في ذلك، أما أنه مثلاً: يبيع عليه، يشتريها ويبيع عليه شيئاً ما هو في ملكه لا، ما يبيع عليه الساعة الذي ما هي في ملكه، إنما هو وكيل، يشتري له الساعة ويعطيه إياها، ولكن له أجرة من باب الوكالة، لا بأس في ذلك، وليس له أن يبيع عليه الساعات ما بعد اشتراها. نعم..","link":"https://binbaz.org.sa/fatwas/4479/حكم-اخذ-الاجرة-على-الوكالة-في-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00815.mp3","categories":["الوصايا","الوكالة"]},{"id":7934,"question":"السؤال الثاني: الشق الأول يقول: هل يحق للشخص الذي يتولى أموره والده أن يوصي من ماله الثلث عند وفاته أو في حياته؟","title":"حكم وصية الولد الذي يتولى أموره والده","answer":"الجواب: إذا كان له مال خاص به معروف فله أن يوصي، أما إذا كان ما له مال، إنما المال لوالده ووالده هو الذي يقوم عليه وينفق عليه فليس له وصية بشيء؛ لأنه ما عنده مال، أما إن كان عنده مال يخصه فلا بأس يستحب له أن يوصي بما.. إذا كان مال كثير يوصي بالثلث أو بالربع أو بالخمس لا بأس، في وجوه البر وأعمال الخير، كالصدقة على الفقراء والمساكين، كتعمير المساجد، كالضحية عنه وعن والديه، كل هذا من القربات.","link":"https://binbaz.org.sa/fatwas/5453/حكم-وصية-الولد-الذي-يتولى-اموره-والده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_066/06604.mp3","categories":["الوصايا"]},{"id":8098,"question":"سؤاله الثالث في هذه الرسالة يقول: أنا اشتغل في المزرعة وموجود فيها عنب ونخل وخضر، وأنا أحمل من هذه الأشياء، مع العلم أننا كلنا على حساب المعزب يقول: وإذا حضر أحد أصدقائنا أطعمناه وبدون علم المعزب، وإذا طلبنا منهم شيء أعطونا من مزرعتهم، وإذا طلبوا منا كذلك شيء نعطيهم من مزرعتنا، وإذا قلنا لهم: هذا حرام، قالوا: هذا أكلنا على حسابه، ونحن نعطيكم من أكلنا، هل يجوز لنا ذلك، وفقكم الله إلى ما فيه خير الدنيا والدين؟","title":"حكم إعطاء أجير المزرعة ضيوفه من المزرعة","answer":"الجواب: هذا فيه تفصيل الكلام فيه إجمال، أما كون الضيف يعطى من الفاكهة الموجودة من غير خبنة يعني لا يحمل شيئاً بل يأكل معكم فلا بأس إن شاء الله، قد جاء في الحديث ما يدل على ذلك، أما أن تهدوه إلى الناس فلا، إلا بإذن صاحب المزرعة، لا تهدوه لأحد إلا بإذن صاحب المزرعة، لكن من زاركم وقدمتم لهم شيء مما في المزرعة من عنب أو بطيخ أو رطب فلا بأس، بحيث يأكل فقط لا يحمل معه شيئاً، ولا تهدوا له شيئاً، بل يأكل معكم من هذا الذي يسره الله، هذا لا بأس به إن شاء الله، أما أن يتخذ معه شيء يخرج به أو تهدوا له شيئاً فلا، إلا بإذن صاحب المزرعة.","link":"https://binbaz.org.sa/fatwas/5892/حكم-اعطاء-اجير-المزرعة-ضيوفه-من-المزرعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08607.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":8218,"question":"إحدى الأخوات المستمعات من الوشم، بعثت تقول: لها أخوان توأمان؛ أخت وأخ وتسأل تقول: هل يجب العدل في التعامل معهما وفي إعطائهما كل شيء؟","title":"حكم العدل بين الإخوة","answer":"الجواب: لا يجب، إنما هذا في الأولاد، النبي ﷺ قال: اتقوا الله واعدلوا بين أولادكم أما الإخوة والخالات والعمات والأقارب الآخرون فلا يجب العدل بينهم، لكن يكون المؤمن حكيماً إذا كان عدم العدل بينهم قد يسبب مشاكل وشحناء فينبغي للمعطي أن يعدل ويتحرى العدل حتى لا تقع بينه وبين قراباته مشاكل، فإذا كان أخوك وأختك، لو أعطيت الأخ وتركت الأخت، قد يكون بينك وبينها مشاكل فأحسني إن الله يحب المحسنين، أعطيها وأعطيه، وجودي عليهما جميعاً، وهكذا لو أعطيتها وتركتيه قد يكون هناك مشاكل فأحسني إليهما جميعاً، أما إذا كان لا يترتب شيء ولا يحصل ضرر، فلا مانع أن تعطيها حاجتها، أو تعطيه كذلك هو، أو تخصيه بشيء أو تخصيها بشيء لا بأس بهذا. نعم.\nالمقدم: بارك الله فيكم، ربما تنطلق أختنا إلى قضية العدل بين التوأمين خاصة؟\nالشيخ: لا، ما يلزم لا في التوأمين ولا في غيرهما، إنما هذا في الأولاد، ليس لها أن تخص بعض الأولاد دون بعض لا الذكور ولا الإناث لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6039/حكم-العدل-بين-الاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09611.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":8224,"question":"إحدى الأخوات المستمعات من الوشم، بعثت تقول: لها أخوان توأمان؛ أخت وأخ وتسأل تقول: هل يجب العدل في التعامل معهما وفي إعطائهما كل شيء؟","title":"حكم العدل بين الإخوة","answer":"الجواب: لا يجب، إنما هذا في الأولاد، النبي ﷺ قال: اتقوا الله واعدلوا بين أولادكم أما الإخوة والخالات والعمات والأقارب الآخرون فلا يجب العدل بينهم، لكن يكون المؤمن حكيماً إذا كان عدم العدل بينهم قد يسبب مشاكل وشحناء فينبغي للمعطي أن يعدل ويتحرى العدل حتى لا تقع بينه وبين قراباته مشاكل، فإذا كان أخوك وأختك، لو أعطيت الأخ وتركت الأخت، قد يكون بينك وبينها مشاكل فأحسني إن الله يحب المحسنين، أعطيها وأعطيه، وجودي عليهما جميعاً، وهكذا لو أعطيتها وتركتيه قد يكون هناك مشاكل فأحسني إليهما جميعاً، أما إذا كان لا يترتب شيء ولا يحصل ضرر، فلا مانع أن تعطيها حاجتها، أو تعطيه كذلك هو، أو تخصيه بشيء أو تخصيها بشيء لا بأس بهذا. نعم.\nالمقدم: بارك الله فيكم، ربما تنطلق أختنا إلى قضية العدل بين التوأمين خاصة؟\nالشيخ: لا، ما يلزم لا في التوأمين ولا في غيرهما، إنما هذا في الأولاد، ليس لها أن تخص بعض الأولاد دون بعض لا الذكور ولا الإناث لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6039/حكم-العدل-بين-الاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09611.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":8247,"question":"هنا رسالة وصلت إلى البرنامج من العراق نينوى (م .ح) الرسالة يقول صاحبها: هل يجوز للرجل أن يكتب إلى زوجته كل ما يملك، ويدع أبناءه من زوجته التي سبقتها؟","title":"حكم الوصية للزوجة الثانية دون الأولى وأولادها","answer":"الجواب: ليس له ذلك؛ لأن الرسول عليه السلام يقول: إن الله قد أعطى كل ذي حق حقه، فلا وصية لوارث هذا إن كانت وصية، أما إن أراد بأن يعجل لها ذلك وأن يعطيها أمواله في حال صحته وحال ثبات عقله وجواز تصرفه، إذا أحب أن يعطيها من ماله شيئاً فلا بأس، ولو لم يعط أولاده شيئاً.\nلكن إذا كان له زوجة ثانية فينبغي له أن يعدل بينهما، أما إذا كان ليس له إلا زوجة واحدة وأحب أن يعطيها نصف ماله أو ثلث ماله أو ماله كله وهو صحيح العقل مرشد فلا بأس عليه في ذلك، ولا يمنع من التصرف بماله في إعطائه زوجة أو تقسيمه بين الفقراء، وقد أنفق أبو بكر  جميع ماله في سبيل الله.. في نصر دين الله رضي الله عنه وأرضاه. نعم.\nلكن كونه يمسك بعض ماله ولا يعجل فهذا خير له، لما أراد كعب -لما تاب الله عليه- لما أراد يتصدق بكل ماله قال له ﷺ: أمسك عليك بعض مالك وهو خير لك كونه يمسك بعض المال؛ ربع المال.. نصف المال أولى حتى لا يحتاج إلى الناس.\nالمقدم: صاحبنا هذا سماحة الشيخ له زوجة متوفاة، وخلفت أولاد، ثم تزوج ثانية ولها أولاد أيضاً، وأشارت عليه بأن يكتب جميع ما يملك باسمها لها ولأولادها، ويترك الزوجة الأولى المتوفاة؟\nالشيخ: هذا فيه نظر، إذا كان القصد لها ولأولادها وله أولاد من الزوجة الأولى ما يجوز.\nأما إذا كان قصد إعطاءها فقط، يعطيها هي فقط، فأما الأولاد لا، فلا بأس أن يعطيها شيئاً من ماله ويمسك ما يسر الله له، أما إذا كان القصد التحيل على أن يعطي أولادها دون أولاد الزوجة الأولى فهذا منكر، والحيل باطلة، والرسول ﷺ يقول: اتقوا الله واعدلوا بين أولادكم. نعم.","link":"https://binbaz.org.sa/fatwas/6045/حكم-الوصية-للزوجة-الثانية-دون-الاولى-واولادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09705.mp3","categories":["الوصايا"]},{"id":8719,"question":"هنا رسالة وصلت إلى البرنامج من النعيرية المنطقة الشرقية، وباعثها أحد الإخوة رمز إلى اسمه بأربعة حروف يقول (م. ح. د. ك) أخونا يقول: أوصت والدتي بثلث مالها واشترينا لها به بيت ويؤجر هذا البيت، وأنفذ ما جاء في الوصية وهو: أضحيتان على الدوام ويزيد بعد الأضاحي والإصلاح نقود، فهل يجوز لي أن أوزع هذه النقود على أولادها مع أنني أفعل ذلك، وهل نصيب الأنثى يساوي نصيب الذكر في هذا الريع، وهل يعطى زوجها الذي توفيت عنه من ذلك؟ أفيدونا أثابكم الله وبارك في حسناتكم.","title":"حكم إعطاء الأقارب مما فضل من الوصية","answer":"الجواب: إذا كانت لم توضح مصرف الفاضل لم تقل: إن الفاضل بعد الضحيتين يصرف في كذا ولا في كذا سكتت فإن الفاضل بعد الضحيتين وبعد الإصلاح لما قد يحتاجه البيت يصرف في وجوه البر وأعمال الخير، ولا يتعين في أولادها ولا في زوجها، لكن إذا كان أولادها فقراء فهم من أولى الناس بالفاضل صدقة وصلة، وهكذا زوجها إذا كان فقيراً يعطى من ذلك من باب أنه كالقريب لحاجته وكونه يعز عليها، فإذا أعطي الزوج الفقير والأولاد من الغلة التي حصلت في البيت بعد الضحيتين والإصلاح هذا حسن ولكن لا يلزم، الوكيل ينظر الأصلح، فلو وجد من هو أفقر من الأولاد وأشد حاجة فلا مانع للوكيل من أن يصرف فيهم.\nالمقصود أن هذا يرجع إلى الوكيل ويتحرى، فإذا كان أولادها فقراء فهم من أولى الناس بالفاضل لكونه في حقهم صدقة وصلة، وهكذا زوجها وهكذا بقية أقاربها كأخوالها وأعمامها وإخوتها ونحوهم، ولكنه لا يتعين ذلك فيهم بل متى رأى الوكيل أن هناك أمراً أكبر من هذا وأشد حاجة فلا بأس أن يصرف فيه، كتعمير المساجد وكالإحسان إلى إنسان مضطر، حاجته أشد منهم جداً، وما أشبه ذلك من الأمور التي قد تعرض يعرف الوكيل أن الصرف فيها مهم جداً، ويرجى فيه الخير للموصية أكثر. نعم.","link":"https://binbaz.org.sa/fatwas/6868/حكم-اعطاء-الاقارب-مما-فضل-من-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_134/13404.mp3","categories":["الوصايا"]},{"id":9190,"question":"السلام عليكم ورحمة الله وبركاته، السائلة (س.م) مصرية الجنسية ومقيمة بدولة البحرين، أقدم شكري وتقديري على ما تقومون به من مجهود في هذا البرنامج، وأتمنى أن يستمر لما فيه من النفع للإسلام وأهله، وسؤالي هو: كان قريب لوالدتي يحفظ عندها وصل أمانة بمبلغ من المال على اثنين من أولاده يدفعونه إلى بنات أخيهم الثالث الذي توفي قبل والدهم، وبعد موت هذا الوالد طلبت والدتي منهم أن يدفعوا المبلغ المذكور في الإيصال إلى بنات أخيهم حسب طلب والدهم ولكنهم رفضوا لخلاف بينهم وبين أمهم زوجة أخيهم، أي: أم البنات، وحاولت معهم كثيرًا ولكن دون جدوى، وتوفيت والدتي وهي في حيرة ماذا تفعل وما زال عندنا هذا الإيصال، هل هذا الإيصال يعتبر بمثابة وصية وتكون والدتي مسئولة عنه، وإذا كانت والدتي مسئولة عنه هل يجوز أن أعطي هذا المبلغ للبنات حتى أبرئ ذمة والدتي من هذا، وهل يكون نفس المبلغ المذكور في الإيصال أم أكثر لفارق المدة، حيث أنه من مدة تقارب خمس عشرة سنة، أرجو إفادتي عن هذه القضية جزاكم الله خيراً؟","title":"حكم الوصية بعد موت صاحبه","answer":"الجواب: هذا الوصل يسلم لأهله؛ لبنات أخيهم كما أوصى والدهم بذلك، وليس لهم تأخير ذلك ولا حبسه وقد أخطئوا في تأخيره وهو في مثابة الوصية، هذا في مثابة الوصية لكن يراعى في ذلك أن أولاد الابن في هذا ليسوا وارثين، فلابد من كون هذا المبلغ يخرج من الثلث، إن كان بقدر الثلث أو أقل من الثلث فإنه يدفع لهم؛ لأنهم لا يرث لبنات ابنه مع أعمامهم والإرث للأعمام، والوصية لغير الوارث مشروعة ولاسيما للأقارب، فالواجب أن يدفع إليهم هذا الأمر إذا كان قدر الثلث فأقل، أما إن كان فيه زيادة فالزيادة لابد من سماح الورثة بها ولا يجوز تأخير ذلك، وعلى من أخره التوبة إلى الله ولا يلزمه الزيادة بل المبلغ يكفيه الذي وصى به ولا تلزمه الزيادة من أجل التأخير، والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7350/حكم-الوصية-بعد-موت-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15105.mp3","categories":["الوصايا"]},{"id":9295,"question":"الرسالة التالية وصلت إلى البرنامج من مدينة الخفجي وباعثها أخونا ناصر عجيم الدوسري، أخونا له مجموعة من الأسئلة سؤال له يقول فيه: متى تشرع الوصية؟ وهل حدد الشرع مبلغاً من المال في ذلك؟","title":"الوصية.. حكمها ومقدارها","answer":"الجواب: الوصية مشروعة دائماً إذا كان للإنسان شيء يوصي فيه فينبغي له البدار بها، وذلك لما ثبت عنه ﷺ أنه قال: ما حق امرئ مسلم له شيء يريد أن يوصي فيه يبيت ليلتين إلا ووصيته مكتوبة عنده رواه الشيخان البخاري و مسلم في الصحيحين، فهذا يدل على أنه يشرع له البدار بالوصية إذا كان عنده شيء يحب أن يوصي فيه.\nوأكثر ما يجوز الثلث فقط، وإن أوصى بالربع أو بالخمس أو بأقل فلا بأس لكن أكثر ما يجوز الثلث لقول النبي ﷺ في حديث سعد الثلث والثلث كثير وقال ابن عباس: لو أن الناس غضوا من الثلث إلى الربع لأن الرسول عليه السلام قال: الثلث والثلث كثير، وأوصى الصديق  بالخمس، فإذا أوصى الإنسان بالربع أو بالخمس كان أفضل من الثلث، ولاسيما إذا كان المال كثيراً، وإن أوصى بالثلث فلا حرج. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7458/الوصية-حكمها-ومقدارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15417.mp3","categories":["الوصايا"]},{"id":9355,"question":"إذا أوصى الإنسان في حياته بأن يدفن في مكان مخصص فهل تنفذ هذه الوصية، يعني: عند الوفاة يدفن في المكان الذي اختاره قبرًا له؟","title":"حكم الوصية بالدفن في مكان معين","answer":"الجواب: إن كانت البقعة مناسبة كأن يقول: في مقابر المسلمين، أو مع الجماعة في مقبرة الجماعة فلا بأس، أما أن يوصي بمحل خاص في بيته، أو في محل آخر فردًا دون الناس فلا، لا تنفذ له الوصية؛ لأن في بيته خلاف المشروع، وهو وسيلة إلى أن يمتهن أو يغلى فيه، وفي مكان آخر وحده قد يمتهن أو يغلى فيه، ولكن يدفن مع المسلمين في بلاده.\nوإن أوصى بنقله إلى بلاد أخرى فلا يجب التنفيذ لما فيه من الكلفة وعدم الحاجة وعدم المشروعية، بل يدفن في مقبرة بلاده إذا كان في مقبرة للمسلمين يدفن معهم، ولا حاجة إلى نقله إلى محل يكلف مئونة.\nأو يكون في نقله إليه محظور آخر كأن يدفن مع أناس معروفين بالبدعة أو معروفين بالكفر والشر لا يدفن معهم، نقله إلى مقابر المسلمين معروفة في بلده يكفي والحمد لله، ولا حاجة إلى أن يتكلف الورثة نقله إلى بلاد أخرى. نعم.\nالمقدم: في بعض المناطق -سماحة الشيخ- المقابر تمتهن فهي مكان للطرقات وعليها تمر الحيوانات وليس لها صيانة، وليس عليها أسوار ولا ما يشبه ذلك، إذا أوصى الإنسان بأن يدفن بعيدًا عن مثل هذه المقابر كأن يدفن في مزرعة بعيدة عن الطرقات مثلًا، فما رأيكم في مثل هذا؟\nالشيخ: إن تيسر مقبرة يدفن في المقبرة مقبرة المسلمين، أما إذا كان في بر أو في مزرعة بعيدة عن الناس فيدفن في محل خاص من أطراف المقبرة هو ومن يموت من جماعته ومن حوله يقبر حول مزرعة فيكون بعيدًا عن الامتهان، ويكون معروف، يكون قبرًا بارز معروف على طريقة القبور هذا لا بأس به، أما يجعل في مكان يمتهن بالمياه أو بالوطء عليه أو ما أشبه ذلك فلا، لكن متى وجدت مقبرة قريبة منهم نقل إليها، حتى لا يمتهن.\nالمقدم: إذًا إذا طلب الإنسان وهو في حياته أن يكون بعيد عن مثل هذه المقابر فهو محق؟\nالشيخ: أي مقابر؟\nالمقدم: هذه المقابر التي تمتهن وهي طرقات...\nالشيخ: إذا وجد مقبرة غير ممتهنة يدفن فيها، والواجب على أهل البلد أن يصونوا مقابرهم، أن يصونوها بالجدار، أو بشبك من الشوك، أو بشبك من الحديد، أو غيره حتى لا تمتهن، والحكومة وفقها الله قد عمدت البلديات هنا بصيانة المقابر، وهي تصان إذا كتب إليهم في هذا وذكروا صانوها والحمد لله، وإذا تساعد أهل البلد وتعاونوا ولم يحتاجوا لحكومة فهذا خير وأفضل.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7519/حكم-الوصية-بالدفن-في-مكان-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18510.mp3","categories":["حمل الميت ودفنه","الوصايا"]},{"id":9732,"question":"هذه رسالة وصلت من السائل (ح. ظ. ف) يقول: سماحة الشيخ ما حكم الإسلام -في نظركم- في كتابة الوالدين لما يملكون لأولادهم قبل الممات؟","title":"حكم توزيع الأب التركة على الأولاد حال حياته","answer":"الجواب: هذه فيه تفصيل: إن كان عطية لأولادهم يعطونهم عطية وهم أصحاء سالمون لا بأس عطية بشرط العدل للذكر مثل حظ الأنثيين، لا يخصون بعضهم دون بعض، يعطونهم جميعًا للذكر مثل حض الأنثيين لا بأس، أما وصية بعد الموت إذا .. وصية من مرض فلا إذا كان هناك ورثة آخرون كالزوجة أو الزوج أو الوالدين لا يوصي بوصية للورثة الورثة لا، يقول النبي ﷺ: إن الله قد أعطى كل ذي حق حقه فلا وصية لوارث وإذا أراد أن يوصي فليس له إلا الثلث، يوصي بالثلث أو أقل. نعم. لغير الورثة.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7887/حكم-توزيع-الاب-التركة-على-الاولاد-حال-حياته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27221.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":11281,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع (م) من الرياض، يقول: إذا مات إنسان ولم يكتب وصيته لجهله أو لغير ذلك، وعندما توفي هذا الشخص جاء أحد الناس وقال: لي في ذمة المتوفى مبلغًا معينًا، فقمنا برد ذلك المبلغ ولكن بعد فترة لضيق ذات اليد، فهل يعذب الميت حتى يقضى دينه وحالنا ما ذكرنا جزاكم الله خيرًا؟","title":"حكم كتابة الوصية","answer":"الجواب:  الوصية للميت مستحبة فيما ينفعه، إذا كان عنده مال كثير يستحب أن يوصي بالثلث أو بالربع أو بالخمس في وجوه البر وأعمال الخير ولا تجب عليه، لكن إذا أراد ذلك فينبغي له أن يبادر ويكتبها لقوله ﷺ: ما حق امرئ مسلم له شيء يوصي فيه يبيت ليلتين إلا ووصيته مكتوبة عنده خرجه الشيخان من حديث ابن عمر . فإذا كان يحب أن يوصي فالسنة أن يبادر وأن يكتب الوصية التي يحب أن يوصي بها في ثلثه في ربعه في خمسه، في بيت معين، في نخل معين، أرض معينة، هذا هو المشروع له وهو الأفضل أن يبادر. أما إذا كان عليه ديون أو عنده أمانات للناس فإن الوصية واجبة يجب أن يوصي بها وأن يبينها لمن خلفه، أن لفلان كذا ولفلان كذا، عنده أمانة لفلان حتى لا يجحدها الورثة، وحتى توصل إلى أهلها. المقصود إذا كان عنده حقوق للناس فيجب عليه أن يوصي بالديون والأمانات ونحوها حتى يبرأ ذمته من حق الناس، نعم. المقدم: بارك الله فيكم، يقولون: إننا تأخرنا في تسديد ذلك الدين لضيق ذات اليد، فهل ... ؟ الشيخ: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، إذا أخروه لعجز مثلًا ما عندهم ما خلف تركة، وهم أحبوا يوفون عنه فلهم أجر ولا شيء عليهم. أما إذا كان عنده تركة فالواجب البدار ببيعها وإيفاء الدين منها حتى لا يتأخر الدين؛ لقول النبي ﷺ: نفس المؤمن معلقة بدينه حتى يقضى عنه، فالبدار ببيع العقار حتى يوفى الدين، أو بيع المواشي والحيوانات أو الأمتعة الأخرى، كون الورثة يبادرون ببيع بعض التركة حتى يوفى عن الميت فهذا واجب، وللقاضي أن يلزمهم بذلك، إذا ترافعوا إلى المحكمة القاضي يلزمهم بذلك. نعم.  المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9456/حكم-كتابة-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37507.mp3","categories":["الوصايا"]},{"id":11285,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع (م) من الرياض، يقول: إذا مات إنسان ولم يكتب وصيته لجهله أو لغير ذلك، وعندما توفي هذا الشخص جاء أحد الناس وقال: لي في ذمة المتوفى مبلغًا معينًا، فقمنا برد ذلك المبلغ ولكن بعد فترة لضيق ذات اليد، فهل يعذب الميت حتى يقضى دينه وحالنا ما ذكرنا جزاكم الله خيرًا؟","title":"حكم كتابة الوصية","answer":"الجواب:  الوصية للميت مستحبة فيما ينفعه، إذا كان عنده مال كثير يستحب أن يوصي بالثلث أو بالربع أو بالخمس في وجوه البر وأعمال الخير ولا تجب عليه، لكن إذا أراد ذلك فينبغي له أن يبادر ويكتبها لقوله ﷺ: ما حق امرئ مسلم له شيء يوصي فيه يبيت ليلتين إلا ووصيته مكتوبة عنده خرجه الشيخان من حديث ابن عمر . فإذا كان يحب أن يوصي فالسنة أن يبادر وأن يكتب الوصية التي يحب أن يوصي بها في ثلثه في ربعه في خمسه، في بيت معين، في نخل معين، أرض معينة، هذا هو المشروع له وهو الأفضل أن يبادر. أما إذا كان عليه ديون أو عنده أمانات للناس فإن الوصية واجبة يجب أن يوصي بها وأن يبينها لمن خلفه، أن لفلان كذا ولفلان كذا، عنده أمانة لفلان حتى لا يجحدها الورثة، وحتى توصل إلى أهلها. المقصود إذا كان عنده حقوق للناس فيجب عليه أن يوصي بالديون والأمانات ونحوها حتى يبرأ ذمته من حق الناس، نعم. المقدم: بارك الله فيكم، يقولون: إننا تأخرنا في تسديد ذلك الدين لضيق ذات اليد، فهل ... ؟ الشيخ: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، إذا أخروه لعجز مثلًا ما عندهم ما خلف تركة، وهم أحبوا يوفون عنه فلهم أجر ولا شيء عليهم. أما إذا كان عنده تركة فالواجب البدار ببيعها وإيفاء الدين منها حتى لا يتأخر الدين؛ لقول النبي ﷺ: نفس المؤمن معلقة بدينه حتى يقضى عنه، فالبدار ببيع العقار حتى يوفى الدين، أو بيع المواشي والحيوانات أو الأمتعة الأخرى، كون الورثة يبادرون ببيع بعض التركة حتى يوفى عن الميت فهذا واجب، وللقاضي أن يلزمهم بذلك، إذا ترافعوا إلى المحكمة القاضي يلزمهم بذلك. نعم.  المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9456/حكم-كتابة-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37507.mp3","categories":["الوصايا"]},{"id":11647,"question":"من جدة رسالة بعث بها المستمع (ط. م. ر) يسأل ويقول: هل يجوز لوالدي أن يحرمني مما يترك لنا من أملاك، وغير ذلك؟ وهل يجوز له أن يكتب كل شيء باسم أخينا الأكبر؟ وما حكم الشرع في ذلك؟ جزاكم الله خيرًا.","title":"حكم حرمان الأب بعض أولاده من العطايا والميراث","answer":"الجواب:  ليس لوالدكم أن يظلمكم، بل يجب عليه أن يعدل في الحياة والموت، يقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم فليس له أن يوصي لبعضكم دون بعض، وليس له أن يعطي بعضكم دون بعض في الحياة، بل يجب أن يترك ماله على شرع الله للجميع، وإن أوصى؛ فيوصي للجميع على حسب الميراث، لا يزيد ولا ينقص، بل على حسب الميراث، وإن أعطى في حياته؛ فعلى حسب الميراث، أما أن يخص بعضًا دون بعض؛ فهذا لا يجوز، بل هو منكر وظلم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9834/حكم-حرمان-الاب-بعض-اولاده-من-العطايا-والميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38921.mp3","categories":["الهبة والعطية","الوصايا"]},{"id":11902,"question":"تقول: خالتي لم تلد، وكتبت لي شقة صغيرة تملكها، وعندها بعض المال، ثم إنها كتبت لي توكيلًا بحيث يكون كل شيء لي بعد وفاتها، ولها أخوان وأخت، ثم إن أحوالهم متوفرة، ولهم أولاد، فهل علي ذنب إن أخذت ما أعطتني؟ وجزاكم الله خيرًا.","title":"مشروعية الوصية ومقدارها وحكم وكالة المرأة","answer":"الجواب:  إن كانت وصية؛ فليس لك إلا الثلث، فأقل، والباقي للورثة، أما إذا أعطتك بحايتها عطية منجزة، ثبتتها في حال صحتها، وعدم مرضها، صحة تامة، وثبت ذلك بالبينة الشرعية؛ فلا بأس؛ تكون عطية، أما ما أعطتك في حال المرض، أو وصية لك؛ فليس لها إلا الثلث، والباقي للورثة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، وبالنسبة للتوكيل أيضًا لبقية التركة؟ جزاكم الله خيرًا.  الشيخ: لا مانع من التوكيل، توكل في ما أوصت به؛ فالتركة لأهلها، لكن إذا كان لها وصية في الثلث، أو في الربع، أو في أقل من ذلك؛ فلها أن توكل من الثقات من شاءت من رجال، أو نساء من أقارب، أو غيرهم، المقصود بالوكالة إذا ثبت فلا بأس إذا كنت أهلًا للوكالة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10086/مشروعية-الوصية-ومقدارها-وحكم-وكالة-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42603.mp3","categories":["الوصايا"]},{"id":11982,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من المستمع إبراهيم آدم من السودان، أخونا له أكثر من قضية في قضاياه، فيسأل في القضية الأولى ويقول: توفي قريب لي، وأوصى بأن يبنى مسجدًا يكون محاذيًا لقبره، فهل تنفذ وصيته، أم لا؟","title":"حكم من أوصى ببناء مسجد بجوار قبره","answer":"الجواب:  لا يجوز تنفيذها، لا يبنى مساجد على القبور ولا عند القبور ولا بين القبور، النبي ﷺ يقول: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد قالت عائشة: يحذر ما صنعوا.  فالمقصود: أن المساجد تكون في محلات مناسبة لأهل البلد، بعيدة عن القبور، أما القبر فلا يبنى عليه، ولا يبنى بين القبور مساجد، كل هذا غلط، كل هذا من أسباب الشرك -نعوذ بالله- من وسائل الشرك، فلا يجوز، بل هذا من أعمال اليهود والنصارى، نسأل الله العافية. فالوصية هذه باطلة لا تنفذ. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10167/حكم-من-اوصى-ببناء-مسجد-بجوار-قبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_430/43005.mp3","categories":["الوصايا"]},{"id":12353,"question":"المستمع حسن صالح سعيد اليماني بعث يقول: لقد توفي والدنا -رحمه الله- منذ ثلاث سنوات، وترك لنا وصية مكتوبة يقول فيها: اذبحوا رأسًا من الغنم في يوم سبعة وعشرين رمضان من كل سنة، ونحن قد قمنا بتنفيذ ذلك لمدة سنتين، وبعدها سافرت أنا وقد تسلفت مبلغًا من المال للسفر للخارج، وبجانب هذا أعول أسرتي التي تتكون من ستة أشخاص، ولم أستطع ذبح هذا الرأس من الغنم؛ لأن راتبي لا يكفي لهذا، فهل يلزمني تنفيذ الوصية في كل سنة؟ وجهوني جزاكم الله خيرًا.","title":"حكم تنفيذ الوصية","answer":"الجواب:  نعم عليك تنفيذ الوصية؛ لأن رمضان شهر مبارك، وليلة سبعة وعشرين من أفضل الليالي، وأحراها بليلة القدر، فإذا كان أبوك أوصاك .. بذبح ذبيحة، أو إخراج مال للصدقة في هذه الليلة، أو في رمضان، أو في أي وقت، أخرجها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10554/حكم-تنفيذ-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39912.mp3","categories":["الوصايا"]},{"id":12559,"question":"هل من الواجب أن يكتب الإنسان وصيته أثناء حياته حتى إذا لم يكن لديه الشيء الكثير؟ فكيف تكتب هذه الوصية؟ وفيم تكون؟","title":"التفصيل في حكم كتابة الوصية","answer":"الجواب:  إنما تكتب إذا كان له شيء يوصي فيه، أما إذا كان ما له شيء يوصي فيه فإنها لا تشرع له؛ لحديث ابن عمر -رضي الله عنهما- عن النبي ﷺ أنه قال: ما حق امرئ مسلم له شيء يريد أن يوصي فيه يبيت ليلتين إلا ووصيته مكتوبة عنده قال: ما حق مسلم له شيء يريد أن يوصي فيه. أما إذا كان ما له شيء، فقير؛ ما عليه شيء، لكن إذا كان عنده مال يريد أن يوصي بالثلث، أو بالربع، أو بالخمس؛ ينبغي له المبادرة، فيكتب الوصية حتى لا يهجم عليه الأجل وهو لم يوص. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10759/التفصيل-في-حكم-كتابة-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41005.mp3","categories":["الوصايا"]},{"id":13311,"question":"أولى رسائل هذه الحلقة رسالة المستمعة أم أحمد الحافي من الدمام، أم أحمد عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها عدد من الأسئلة، فتسأل في سؤالها تقول: رجل استثمر أموال زوجته مع أمواله، وهي شبه راضية، وكانت زوجته تطالبه بأن يكتب لها شيئًا في العقار على قدر نقودها؛ لكي تضمن أن نقودها لا تذهب إلى الورثة بعد وفاته، ولكن زوجها كان يقول لها: إن هذه الأموال -يقصد أمواله زايد أموالها- لك ولأبنائك من بعدي، فتوفي قبل أن يكتب لها شيئًا بقدر أموالها، فهل يلحقه شيء في ذلك؟ وماذا على الورثة تجاه هذا الموضوع؟ جزاكم الله خيرًا.","title":"ما الواجب فيمن مات ولم يبين أنه مديون لزوجته؟","answer":"الجواب: باسم الله، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن الواجب على الزوج -إذا كان عنده مال لزوجته- أن يكتب ذلك، وأن يوضح ذلك في وثيقة ثابتة؛ حتى تسلم لها بعد موته لو مات، ويجب أن يوضح ذلك في صحته؛ حتى تبرأ ذمته، وإذا مات، ولم يبين ذلك؛ وجب على الورثة أن يؤدوا حقها من رأس التركة، كسائر أهل الدين، إذا ثبت ذلك بالبينة، أو سمحوا بذلك لها، وأعطوها وصدقوها، إذا كانوا مرشدين مكلفين. ولا يجوز للزوج، ولا غيره -إذا كان في ذمته دين لأحد- أن يسكت، وأن يغفل عن ذلك؛ فتضيع الحقوق، فإن هذا خطر عظيم، وظلم عظيم يجب الحذر منه، والواجب على كل إنسان عنده حق للغير -سواء كان زوجًا أو غير زوج أو زوجة وغير ذلك- أن يبين، ويكتب الدين في وثيقة شرعية عند المحكمة، أو عند كاتب معروف يعتمد قلمه؛ حتى يؤدى الحق إلى صاحبه لو قدر الله الموت قبل التسديد. وهذه المرأة يجب على الورثة أن يعطوها حقها، إذا ثبت لديهم ذلك، فإن لم يثبت لديهم؛ فليس عليهم شيء، والله يعوضها عن ذلك، وقد أساء زوجها، وتعاطى ما لا يحل له، وهي بالخيار إن أباحته وسامحته؛ فلها أجرها، وإن لم تسمح؛ أعطيت حقها يوم القيامة، ولا يضيع عليها شيء. فأنت أيها الأخت في الله السائلة: إن سمحت وأبرأت الزوج؛ فجزاك الله خيرًا، وإن لم تسمحِ، ولم يعطوك حقك -يعني الورثة- فالأمر إلى الله، والحساب بينك وبينه عند الله  الله المستعان. نعم. المقدم: الله المستعان جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11597/ما-الواجب-فيمن-مات-ولم-يبين-انه-مديون-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60701.mp3","categories":["الوصايا"]},{"id":13601,"question":"السائل مصري، ويعمل بالمملكة الأردنية الهاشمية يقول في هذا  البعض من الناس يوصي بدفنه في المدينة النبوية، هل تنفذ مثل هذه الوصية، وهل لذلك فضل؟","title":"هل تنفذ وصية من أوصى بدفنه في المدينة؟","answer":"الجواب: الأقرب عدم التنفيذ، لا حاجة إلى التنفيذ، يدفن في بلده مع المسلمين، ولا يكلف ورثته، ولا يكلف الناس، يدفن مع المسلمين في بلده إذا كان فيها مقبرة للمسلمين، وإلا يقبر في محل مبتعد عن الكفار، ولا حاجة إلى النقل. نعم. المقدم: سماحة الشيخ! من مات أيضًا في بلد الكفار هل يدفن عندهم؟ الشيخ: يدفن في محل مستقل، ما هو مع قبورهم، إما في محل المسلمين، وإلا في محل بعيد عن قبورهم، خالي من قبورهم. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11936/هل-تنفذ-وصية-من-اوصى-بدفنه-في-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52721.mp3","categories":["الوصايا"]},{"id":14403,"question":"السائل حسن إسماعيل من اليمن يقول: إذا مات الرجل، وأوصى قبل موته أن يذبحوا رأسًا من الغنم أو أكثر أثناء الدفن، وتقسم على الحاضرين، فهل أكلها جائز؟","title":"حكم وصية من أمر بالذبح وتوزيع اللحم أثناء دفنه","answer":"الجواب: هذه بدعة، لا تنفذ، هذه وصية بدعة، ليس لهم تنفيذها، نعم.","link":"https://binbaz.org.sa/fatwas/12885/حكم-وصية-من-امر-بالذبح-وتوزيع-اللحم-اثناء-دفنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55222.mp3","categories":["الوصايا","البدع والمحدثات"]},{"id":14655,"question":"على بركة الله، نبدأ هذا اللقاء بسؤال لأحد الإخوة، لم يذكر الاسم في هذه الرسالة، ويسأل سماحة الشيخ عن حكم الوصية هل هي واجبة؟ بمعنى: أي أنه لا بد لكل إنسان أن يوصي، حتى ولو كان لم يكن يملك شيئًا من المال؟ وهل يجوز للإنسان أن يوصي بالثلث لابنه الأكبر؟جزاكم الله خيرًا.","title":"حكم الوصية، وهل تجوز للوارث؟","answer":"الجواب: بسم الله الرحمن الرحيم.\nالحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالوصية سنة إذا كان له شيء يوصي فيه بالثلث فأقل، إذا كان عنده مال فلا بأس أن يوصي بالثلث فأقل، أما إذا كان ماله قليل، فالأحسن عدم الوصية يتركه للورثة، أما إذا كان ماله فيه خير، وفيه بركة، فلا مانع أن يوصي بالثلث، يستحب أن يوصي بالثلث أو بالربع أو بالخمس في وجوه الخير، كأن يقول في الصدقة على الفقراء، في تعمير المساجد، في صلة الرحم، في ضحية لي ولأهل بيتي، أو لي ولوالدي، أو ما أشبه ذلك من وجوه البر، أو في سبيل الله، يعني: في الجهاد في سبيل الله، لكن إذا عين الجهة تكون أحسن للفقراء والمساكين، كتعمير المساجد حتى يكون الوكيل على بينة، ويكون له وكيل، يجعل هذه الوصية لها وكيل من أقاربه من أولاده من غيرهم. وهكذا لو كان عليه دين ما عليه بينات يجب أن يوصي به، إن لفلان كذا، ولفلان كذا، حتى لا تضيع حقوق الناس، أما إن كان عندهم وثائق، فالحمد لله، لكن إذا أوصى به احتياطًا خشية أن تضيع وثائقهم، أو نحو ذلك، إذا أوصى به احتياطًا لفلان عندي كذا، ولفلان عندي كذا احتياطًا، فهذا طيب، وهذا حسن. كذلك إذا أحب أن يخص أحدًا بعطية من غير الورثة، كأن يقول: لخالتي كذا، ولفلانة كذا، أو فلان كذا، الثلث فأقل يعطيهم فلا بأس، أما الورثة لا يوصي لهم بشيء، لا أبنائه ولا غيرهم، ليس للورثة وصية، النبي ﷺ يقول: لا وصية لوارث أما غير الورثة فلا بأس، كأن يوصي لعمته لخالته لشخص آخر لا يرث من أقاربه بالثلث بدراهم معينة أقل من الثلث ببيت بأقل من الثلث، بسيارة أقل من الثلث، وما أشبه ذلك لا بأس؛ لقوله ﷺ: ما حق امرئ مسلم له شيء يريد أن يوصي فيه يبيت ليلتين إلا ووصيته مكتوبة عنده هكذا رواه ابن عمر عن النبي ﷺ، متفق على صحته. فقول الرسول ﷺ: ما حق امرئ له شيء يريد أن يوصي فيه يدل على أن الوصية لمن له شيء يريد أن يوصي فيه، أما إنسان ما عنده شيء ما تشغله الوصية، أو عنده شيء لكن ما يريد أن يوصي، ما تلزمه الوصية، ولكن إذا أراد أن يوصي يوصي، يشهد على الوصية، ويكتب كتابة موثوقة حتى تعتمد، سواء الوصية بالثلث أو بالربع أو بالخمس أو بأقل في وجوه البر في حج في عمرة في ضحية، أو وصية لإنسان يعطيه من أقاربه غير الورثة كأقارب من غير وارث خال، عم، أخ ما يرث لا بأس.  أما الوارث لا يوصى له؛ لأن الرسول يقول ﷺ: لا وصية لوارث يكفي حقه الذي قسم الله له، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13146/حكم-الوصية-وهل-تجوز-للوارث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56001.mp3","categories":["الوصايا"]},{"id":14717,"question":"المستمع شعبان محمد عبدالمعطي، يقول: أنا مواطن عربي، ولي سؤال يحيرني دائمًا: أنا مسافر منذ سنتين إلى بلد عربي، وقبل سفري قالت لي أمي: إذا مت وأنت موجود في بلدنا أرجو منك أن تدفني بعيدًا عن أهلك، وشاءت الأقدار أنها توفيت وأنا في السفر، فهل يصح عند عودتي من السفر أن أنقلها إلى مكان آخر؟","title":"حكم نقل الميت بعد دفنه تنفيذًا لوصيته","answer":"الجواب: لا، بل ما دامت دفنت في محل بين المسلمين فلا تنقلها، ولو كنت حاضرًا لم تلزمك هذه الوصية، بل تدفنها في المحل المناسب، ولو كان بخلاف وصيتها؛ لأن الوصية التي تخالف شرع الله لا يلزم تنفيذها، فلو كنت حاضرًا شرع لك دفنها في المحل المناسب بين المسلمين، وإذا كنت غائبًا وقد دفنت في محل بين المسلمين فلا تنقلها.  أما إذا كانت دفنت في محل بين الكفار، أو في محل غير لائق في طريق الناس قد يطؤها الناس، أو في محل عليه خطر من السيل يجرفه، فلا بأس أن تنقلها إلى محل مناسب بين المسلمين من باب الإحسان، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13213/حكم-نقل-الميت-بعد-دفنه-تنفيذا-لوصيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63709.mp3","categories":["حمل الميت ودفنه","الوصايا"]},{"id":15177,"question":"سماحة الشيخ، هذه سائلة تقول: شخص توفي ولم يحج، فحج أولاده عنه، وبعد فترة من الزمن وجدوا الوصية مكتوبًا عليها أن يحجوا عنه، فهل تكفي الحجة الأولى الذي قام بها الأولاد، أم يلزمهم أن يحجوا مرة ثانية؟","title":"حكم من حُج عنه ثم وجد وصية بأن يُحج عنه","answer":"الجواب: الذي يظهر -والله أعلم- يحجون عنه حسب الوصية حجة ثانية، ولو حجوا أكثر فلا بأس، لكن الوصية الذي أوصى بها ينفذوها؛ لأن الوصية التي أدوها تبرعًا منهم، نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13664/حكم-من-حج-عنه-ثم-وجد-وصية-بان-يحج-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56419.mp3","categories":["الوصايا"]},{"id":15307,"question":"هذه سائلة للبرنامج أرسلت بمجموعة من الأسئلة تقول: سماحة الشيخ، رجل توفي وأوصى في وصيته بأن يضحى لوالديه، ورفض الأولاد معللين بأن ذلك بدعة، وجهونا في ضوء هذا السؤال، ما الحكم في ذلك؟ مأجورين.","title":"حكم تنفيذ وصية من أوصى بالأضحية عنه وعن والديه","answer":"الجواب: الواجب تنفيذ الوصية، إذا أوصى لوالديه تنفذ الوصية، تذبح الضحية عنه وعن والديه، كما أوصى بذلك، فيقال: عنه وعن والديه، عن فلان ووالديه.  وليست الضحية بدعة عن الوالد وإلا عن الوالدة، بل هي مشروعة، بنية الصدقة، والقول بأنها بدعة غلط، قاله بعض الناس غلطًا منه، والضحايا سنة عن الحي والميت جميعًا، الواجب تنفيذ الوصية عن الموصي ووالديه، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13804/حكم-تنفيذ-وصية-من-اوصى-بالاضحية-عنه-وعن-والديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56602.mp3","categories":["الوصايا"]},{"id":15457,"question":"سؤاله الآخر يقول: هل يصح أن يوصي الميت في حياته بدفنه في المكان الفلاني، أو إلى جانب الشخص الفلاني؟ وإن حصل شيء من ذلك فهل على أهله تنفيذ طلبه في دفنه حيث أوصى؟","title":"حكم الوصية بالدفن في مكان معين، وحكم تنفيذها","answer":"الجواب: لا بأس أن يوصي أن يدفن في المقبرة الفلانية، أو بجوار فلان؛ لأنه قد يكون له قصد في ذلك؛ لأنهم من الصلحاء والأخيار، فلا بأس أن يدفن مع الصلحاء والأخيار، وإن أوصى بذلك فلا بأس، وعلى الوصي أن ينفذ هذه الوصية إذا استطاع تنفيذها إذا تيسر تنفيذها.  أما إذا لم يتيسر تنفيذها؛ لعجزه عن ذلك، أو لبعد المسافة، أو ما أشبه ذلك، فلا حاجة إلى التنفيذ، ويدفن في أي مقبرة من مقابر المسلمين، والحمد لله. وإذا كانت المقبرة بعيدة من بلد إلى بلد فلا وجه لهذه الوصية، ولا حاجة إلى تنفيذها، بل يدفن في مقبرة بلده إذا كانت مسلمة، أو في مقبرة أخرى من قبور المسلمين، ويكفي، ولا حاجة إلى أن يتكلفوا من التركة أموالًا لنقله بالطائرات أو غيرها، هذا لا حاجة إليه، ما دام يوجد مقبرة مسلم يدفن فيها، فالحمد لله، ولا حاجة إلى تنفيذ هذه الوصية؛ لأنها وصية لا وجه لها شرعًا. أما إذا كان الدفن في المقبرة التي أراد متيسر في جانب البلد في طرف البلد؛ لأن البلد فيها مقابر، واختار واحدة منها، فالأمر في هذا واسع، والتنفيذ أولى، نعم. المقدم: حتى لو اختار في نفس القبر، يعني: يدفن مع شخص آخر في قبر .\nالشيخ: أجل بجواره، لا بأس بجواره. المقدم: بجواره؟\nالشيخ: نعم، إذا تيسر. المقدم: نعم؟ الشيخ: إذا تيسر هذا أولى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13986/حكم-الوصية-بالدفن-في-مكان-معين-وحكم-تنفيذها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68705.mp3","categories":["حمل الميت ودفنه","الوصايا"]},{"id":15578,"question":"هذا سؤال من المستمع حسن أحمد، من الرياض، يقول: والدي توفي وأوصى بثلث ماله في أعمال بر كإصلاح مشرب ماء، أو تكييف مسجد، أو إنارته، ونحو ذلك. وأنا حاليًا الوصي على تنفيذ هذه الوصية، وأرغب في أن أحصر ثلث ماله في أرض لمسجد يقام عليه، أرجو إفادتي عن صحة عملي هذا؟أثابكم الله.","title":"حكم بناء مسجد لمن أوصى بثلث ماله في أعمال البر","answer":"الجواب: الواجب أن يشترى بالثلث عقارًا يكون وقفًا في أعمال البر، فإذا كان الثلث كثيرًا يمكن أن يشترى به عقارًا، بيتًا، أو دكانًا أو مزرعة جيدة تغل، حتى تصرف الغلة في أعمال البر، فهذا هو الواجب، حتى لا يعدم الوقف، بل يبقى الوقف مستمرًا. فأنت -أيها الوكيل- تشتري عقارًا بالثلث وغلة العقار تصرف في تعمير المساجد، في صدقة على الفقراء والمساكين، في الإحسان إلى الأقارب الفقراء، في أشباه ذلك من وجوه البر، أما إن كان الثلث قليلًا لا يتيسر به دكان ولا بيت ونحو ذلك فلا مانع من صرفه في تعمير مسجد حتى لا يضيع.\nالمقدم: إنما لو أراد أن ينتهي من هذا العبء بعمارة مسجد على أرض يشتريها من هذا الثلث لا يصح هذا ؟\nالشيخ: ليس بظاهر، الأولى ترك ذلك، الأقرب عندي أن هذا لا يصلح؛ لأن هذا خلاف ما أراده الموصي، الموصي أراد عقارًا تنفق غلته في وجوه البر، هذا مراد الموصي، على العادة المعروفة عند الموصين، لو أراد مسجدًا لقال: يجعل في مسجد، وانتهى، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14119/حكم-بناء-مسجد-لمن-اوصى-بثلث-ماله-في-اعمال-البر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69204.mp3","categories":["الوصايا"]},{"id":15607,"question":"له سؤال أخير يقول: رجل قبل أن يتوفى كتب كل ما يملكه من أموال لبناته فقط بقصد حرمان بقية ورثته الآخرين، فهل ما فعله هذا جائز أم لا؟ وإذا لم يكن جائزًا، فما العمل في تركته؟","title":"حكم الوصية بحرمان بعض الورثة من الميراث","answer":"الجواب: إذا كان أوصى بالمال لبناته أو لبعض ورثته فالوصية باطلة؛ لأن الرسول ﷺ قال: إن الله قد أعطى كل ذي حق حقه، فلا وصية لوارث فليس لأحد أن يوصي بالمال لبعض الورثة لا لبنات ولا غير بنات، بل المال يكون للجميع، أما إذا أوصى بالثلث، أو أقل لغير الورثة هذا صحيح، له أن يوصي بالثلث فأقل، لكن لغير الورثة، فإذا ثبت ذلك بالبينة العادلة نفذ، أما أنه يوصي للزوجة أو توصي المرأة لزوجها أو لأبيها أو لأمها أو لبناتها أو يوصي الزوج لأمه أو لأبيه أو غيره من الورثة، لا، غير صحيح، لا يوصى للوارث أبدًا لا بقليل ولا بكثير، بل الله -جل وعلا- قسم بينهم في المال، فيجب أن يبقى لهم حكم الله في ذلك، وليس للمسلم أن يوصي بشيء للورثة. أما إن كان قد أعطاهم في الصحة، قد أعطى بناته بعض المال في صحته وسلامته، وليس له أولاد آخرون، بل بنات فقط، أو أعطى أولاده جميعًا، وسوى بينهم في صحته، قسم بينهم، فإن هذا نافذ، وليس لأحد الاعتراض عليه إذا كان في الصحة، ما هو في المرض، ليس وصية، بأن مثلًا في صحته عنده بنتان وولد فأعطاهم مثلًا أراضٍ، أعطاهم بيوت، أعطاهم نقود، قسمها بينهم، لا بأس لا حرج، وعدل بينهم لا حرج لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ [النساء: 11] أو له زوجة وأعطاها في صحته بيتًا، أو أعطاها أرضًا، أو سيارة لا بأس، أو أعطى بعض أقاربه الآخرين الوارثين، أعطى بعض إخوته الورثة في صحته فلا بأس، نعم. المقدم: أحسن الله إليكم وأثابكم.","link":"https://binbaz.org.sa/fatwas/14147/حكم-الوصية-بحرمان-بعض-الورثة-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_694/nour_69407.mp3","categories":["الوصايا"]},{"id":15868,"question":"بعد هذا ننتقل إلى رسالة بعث بها المستمع أحمد عبيد المبسر العتيبي، أخونا يسأل سماحتكم عددًا من الأسئلة في أحدها يقول: ما هي الأشياء التي يصرف فيها مال الميت الذي وصى به؟جزاكم الله خيرًا.","title":"الوصية تنفذ حسب كلام الموصي","answer":"الجواب: الوصية يراعى فيها كلام الموصي وتوجيهاته، فإن كان قال: تصرف في أعمال البر تصرف في وجوه البر: صدقة على الفقراء، تعمير المساجد، شراء حاجات للمساجد، وأشباه ذلك، كإصلاح دورات المياه، مساعدات للمجاهدين، وغير هذا من وجوه الخير، فإن كان قال في وصيته: تصرف في تعمير المساجد؛ تعمر به المساجد، وإن قال في أقاربه الفقراء؛ تصرف في أقاربه الفقراء، فهو ينظر فيما قال، ويعمل بوصيته، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14458/الوصية-تنفذ-حسب-كلام-الموصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74408.mp3","categories":["الوصايا"]},{"id":16252,"question":"نختم هذا اللقاء -يا سماحة الشيخ- بهذا السؤال يقول: بالنسبة إلى الوصية التي تخالف الشرع، هل تنفذ، أم لا؟ وكيف يتصرف الموصى إليه في هذه الوصية؟","title":"هل تنفذ الوصية المخالفة للشرع؟","answer":"الجواب: الوصايا المخالفة لا تنفذ، الوصايا إذا خالفت الشرع لا تنفذ، لا ينفذ منها إلا ما وافق الشرع، فإذا أوصى الإنسان مثلًا في ماله بأكثر من الثلث، لا ينفذ إلا الثلث، إلا برضا الورثة المرشدين إذا رضوا بالزيادة، وإذا أوصى بمال في معصية كأن يشترى به خمرًا، أو يشترى به شيئًا من آلات الملاهي؛ لا تنفذ الوصية، وهكذا لابد من الوصية تكون موافقة للشرع، لابد أن تكون الوصية، أو أوصى للورثة، لبعض الورثة، لا وصية لوارث، لابد أن تكون وصية مطابقة للشرع، موافقة للشرع.","link":"https://binbaz.org.sa/fatwas/14919/هل-تنفذ-الوصية-المخالفة-للشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58019.mp3","categories":["الوصايا"]},{"id":16906,"question":"تقول الأخت (د. الحربي) من السويدرة: عندي أيتام، وهم أبناء أخي، وأنا الذي أخدمهم، وأوفر لهم ما يطلبون، وهم يستلمون الضمان، فهل يجوز لي أن آكل من هذا المال الذي تدفعه لهم الدولة، أم لا يجوز لي ذلك؟ جزاكم الله خيرًا.","title":"حكم أخذ الوصي من مال الأيتام لديه","answer":"الجواب: لا حرج عليك أن تأكلي بالمعروف؛ لأن الله -جل وعلا- رخص في ذلك، قال -جل وعلا-: وَمَنْ كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ وَمَنْ كَانَ فَقِيرًا فَلْيَأْكُلْ بِالْمَعْرُوفِ [النساء:6] فإذا كنت في حاجة؛ فكلي معهم، وإذا كنت غنية؛ فكلي من مالك، واحفظي مالهم، وأنفقي عليهم منه، وأما إذا كنت محتاجة؛ فكلي معهم، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15664/حكم-اخذ-الوصي-من-مال-الايتام-لديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71913.mp3","categories":["الوصايا"]},{"id":18092,"question":"والدي قال لي ولإخوتي أثناء جلوسه معنا: لنا قطعة أرضٍ بجوار المنزل، هذه القطعة إن شاء الله، تبنوا عليها مسجدًا، ومر مدة على هذا الكلام، حتى يسر الله علي بالمال، وأثناء تنفيذي وصية والدي، وبناء المسجد، حدثني البعض: أن المساجد في البلد كثيرة، ويمكن أن تتبرع بالمبلغ للمعهد الديني الذي سيقام في البلد، فهل المسجد أولى؟ أم المعهد أولى؟ جزاكم الله خيرًا.","title":"حكم تقيد الورثة بوصية والدهم","answer":"الجواب: ينظر في الأمر إن كان المكان في حاجة للمسجد، تتشاورن مع أهل المحل، السكان، وتنظرون في حاجة المنطقة إلى المسجد، أو تستعينون بالمحكمة، حتى ينظر في الأمر، فإذا كانت المنطقة تحتاج إلى مسجد، فاعمروا المسجد في الأرض التي سماها والدك. أما إن كانت المنطقة في غير حاجة؛ فإنكم تبيعون الأرض هذه، وتبنون مسجدًا في محل آخر، يعني مقصود الوالد هو بناء المسجد، فإذا كانت المنطقة في غنية عن هذه الأرض وعن هذا المسجد، فإن الأرض تباع، ويصرف ثمنها في أرضٍ أخرى، في محلٍ محتاج للمسجد، تعمرونها هناك، وتوفون بالوصية، وصية والدكم وأرضه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا المعهد لا يفكرون فيه؟ الشيخ: لا لا لا. مسجد بمسجد، الذي أوصى به للمسجد، يكون للمسجد. نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17127/حكم-تقيد-الورثة-بوصية-والدهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73016.mp3","categories":["الوصايا"]},{"id":18586,"question":"ننتقل إلى رسالة أخرى، وموضوع آخر، الرسالة وصلت إلى البرنامج من اليمن لواء حجة، وباعثها أخونا ربيع علي جيران حجوري، أخونا يقول: أنا لي أم متوفاة إلى رحمة الله  من اثني عشر عامًا، ولها أولاد ثلاثة: توفي منهم اثنان ولم يبق إلا الله  وأنا العبد الفقير إلى الله، ووالدي ما زال على قيد الحياة، وله زوجة أخرى، ولها أولاد لوالدي.والمرحومة الوالدة تركت شيئًا بسيطًا من المال، وأنا لم آخذ منه شيئًا، وهو مع والدي، وقبل وفاة المرحومة والدتي أوصتني بحجة لها -زيارة بيت الله الحرام- مقابل هذا المال الذي تركته، وهذا المال موجود طرف والدي الحي، وقد طلبت هذا المال من والدي؛ فرفض إعطائي أية مبلغ، علمًا بأن والدتي قالت: إنك لا تحج إلا من مالها الحقيقي الذي تركته.والسؤال الآن هو: هل يجوز في الشرع أن يستولي والدي على أموال المرحومة والدتي بدون وجه؟ وهل يصح أن أحج لها من أموالي الخاصة بي؟الرجاء التكرم بالإفادة، جزاكم الله عني خيرًا.","title":"حكم تنفيذ وصية الميت في الحج عنه من ماله","answer":"الجواب: أولًا: تقول: إلا الله، ثم أنا.  وثانيًا: قولك المرحومة، هذا الجزم لا وجه له، ولكن تقول: والدتي -رحمها الله- تدعو، أو غفر الله لها، ولا تقول: المرحومة، والمغفور لها؛ لأن هذا لا يعلمه إلا الله، فالجزم بمثل المرحومة، والمغفور لها أمر لا يجوز؛ لأن أهل السنة والجماعة لا يشهدون لأحد برحمة ولا مغفرة ولا جنة ولا نار، إلا من شهد الله له، أو شهد له الرسول -عليه الصلاة والسلام- بذلك، فمثل هذا الكلام يقع من كثير من الناس يقول: كان المرحوم، فلانة المرحومة، فلان المغفور له، وهذا لا ينبغي، بل الواجب أن يقول: غفر الله له، رحمه الله من دون جزم. وأما هذه الوصية: فالواجب على أبيك وعليك وعلى جميع الورثة أن ينفذوا وصيتها بالثلث فأقل، ينفذوا الحجة فيما يبلغ الثلث فقط أو أقل، إذا كانت قد حجت، أما إذا كانت لم تحج الفريضة ينظر في حالها، فإن كانت مليئة في حياتها قادرة؛ فالواجب إخراج الحجة من مالها قبل كل شيء، كالدين يحجج عنها، أما إن كانت غير مؤسرة في حياتها، والمال الذي خلفت قليل لا تكون به مؤسرة في حياتها، فإن وصيتها تنفذ في الثلث فأقل، فالثلث يؤخذ من مالها وتحج به أنت كما أوصتك به أمك، وإن تركت المال لأبيك وحججت عن والدتك من نفسك؛ لئلا يحصل بينك وبين أبيك نزاع وشنآن وبغضاء ووحشة؛ فلا بأس، حج عنها من نفسك، والحمد لله، وإذا تركت المال لأبيك؛ فأنت على خير ومأجور، لما لأبيك من الحق العظيم؛ ولأن في ترك ذلك بعدًا عن الشحناء بينك وبين أبيك. والمقصود: حصول الحجة، فإذا حججت عنها من مالك، واستغنيت عن مالها؛ مراعاة لخاطر أبيك، فلا بأس بذلك ولا حرج، بل ذلك هو المطلوب وهو الأولى والأفضل؛ حسمًا لمادة النزاع بينك وبين والدك، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17737/حكم-تنفيذ-وصية-الميت-في-الحج-عنه-من-ماله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_871/nour_87104.mp3","categories":["الوصايا"]},{"id":18812,"question":"هذا السائل (محمد . أ. أ) من قطر يقول: رجل أوصى بثلث ماله وقفًا، فضاعت الوصية، وقسمت التركة، وبعد فترة من الزمن عثر على الوصية، فما الحكم في ذلك؟","title":"حكم الوصية إذا عثر عليها بعد قسمة التركة","answer":"الجواب: هذه مسألة مهمة يرجع فيها للمحكمة، حتى يعرف الحقيقة، وتثبت الدعوى أنها ضاعت الوصية، وأن الوصية ثابتة، المقصود هذا موضوع يرجع فيه للمحكمة في البلد، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17958/حكم-الوصية-اذا-عثر-عليها-بعد-قسمة-التركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79124.mp3","categories":["الوصايا"]},{"id":19454,"question":"يقول أخونا: أنا شاب مسلم أريد أن أوصي أهلي ما دمت على قيد الحياة، ذلكم أن الرسول ﷺ قد أمرنا بذلك في قوله ﷺ: ما حق امرئ مسلم يبيت ليلتين وله شيء يريد أن يوصي فيه إلا ووصيته مكتوبة عند رأسه - هكذا كتب شيخ عبد العزيز - وقال ابن عمر رضي الله عنهما: ما مرت علي ليلة منذ سمعت رسول الله ﷺ قال ذلك إلا وعندي وصيتي أرجو من سماحتكم أن يدلنا على المهم في الوصية؟","title":"مشروعية الوصية وبيان بعض أحكامها","answer":"الجواب: نعم، يشرع للمؤمن أن يوصي بما يلزمه من ديون أو حقوق حتى تسلم إلى أهلها، ولاسيما إذا كانت ليس عليها وثائق، وقد تضيع على أهلها، فإن الواجب عليه أن يوصي بذلك حتى يؤدي الحقوق، أما إن كان عليها وثائق عند أهلها فالأمر في هذا واسع، وإذا كان له شيء يريد أن يوصي فيه عنده مال يوصي بالثلث أو بالربع أو بالخمس في وجوه البر، وأعمال الخير؛ فينبغي له أن يكتب ذلك قبل أن تدركه المنية، فإن الأجل لا يدرى متى ينزل، وعلمه عند الله  فالمشروع البدار بذلك للحديث الذي ذكره السائل وهو قوله ﷺ: ما حق امرئ مسلم له شيء يريد أن يوصي فيه يبيت ليلتين إلا ووصيته مكتوبة عنده هذا رواه الشيخان: البخاري ومسلم في الصحيحين، فهو يدل على شرعية المبادرة، والمسارعة إلى الوصية إذا كان له شيء يريد أن يوصي فيه. ومن ذلك الوصية بالديون التي ليس عليها وثائق فيقول: عندي لفلان كذا، وعند لفلان كذا، وعندي وديعة لفلان حتى لا تضيع عليه حقوقهم، وهذا شيء واجب، والمستحب أن يوصي أيضًا بالثلث، أو بالربع، أو بالخمس إذا كان عنده مال فيه سعة يوصي بذلك في وجوه البر وأعمال الخير، كالصدقة على الفقراء، والمساهمة في الجهاد في سبيل الله، وتعمير المساجد، والربط للفقراء، والمراكز الإسلامية، والجمعيات الإسلامية ونحو ذلك من وجوه الخير، ولا مانع أن يجعل فيه ... له، أو له ولوالديه، أو له ولأهل بيته كل سنة، لا مانع من ذلك لا حرج في ذلك، كل ذلك من القرب. ويوصي على ذلك بالشخص الثقة يعني: يعين على هذه الوصية من يراه ثقة من أولاده، أو إخوته أو غيرهم حتى تحفظ الوصية وحتى لا تضيع، وله أن يسندها إلى غير أقاربه كأن يقول: الوكيل فلان من أصدقائه، ومعارفه الثقات غير الأقارب، وله أن يقول: هو الوصي وله أن يوصي بعده من يرى من الثقات فيستنيبه في أن يوصي بعده من يرى، كل هذا لا بأس به لحفظ الوصية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18706/مشروعية-الوصية-وبيان-بعض-احكامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_944/nour_94406.mp3","categories":["الوصايا"]}]
